export const questions: Question[] = [
  { id: "y2in10-001", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 01", difficulty: "Challenge", questionText: "A population satisfies \\(\\displaystyle\\frac{dP}{dt} = 0.1P\\) with \\(P(0) = 100\\). Find \\(P(5)\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = 0.1P", explanation: "The rate of change of population is proportional to the current population, with growth constant \\(k = 0.1\\). This is the classic continuous-exponential-growth law: more individuals \\(\\Rightarrow\\) more births \\(\\Rightarrow\\) faster growth." }, { stepNumber: 2, description: "Identify the DE type and separate variables.", workingLatex: "\\displaystyle\\frac{dP}{P} = 0.1\\,dt", explanation: "It is first-order and separable: gather all \\(P\\)-terms on one side and all \\(t\\)-terms on the other before integrating." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dP}{P} = \\displaystyle\\int 0.1\\,dt \\;\\;\\Rightarrow\\;\\; \\ln|P| = 0.1t + C", explanation: "Left-hand side is the standard log integral \\(\\displaystyle\\int \\displaystyle\\frac{dP}{P} = \\ln|P|\\); right-hand side is a constant times \\(t\\)." }, { stepNumber: 4, description: "Exponentiate to solve for \\(P\\) explicitly.", workingLatex: "P = e^{0.1t + C} = A e^{0.1t}, \\;\\; A = e^{C}", explanation: "Lift both sides to \\(e^{\\,\\cdot\\,}\\); the arbitrary constant \\(C\\) absorbs into a new positive constant \\(A\\). Since \\(P > 0\\) we drop the modulus." }, { stepNumber: 5, description: "Apply the initial condition \\(P(0) = 100\\).", workingLatex: "100 = A e^{0} = A \\;\\;\\Rightarrow\\;\\; A = 100 \\;\\;\\Rightarrow\\;\\; P(t) = 100 e^{0.1t}", explanation: "Substitute \\(t = 0\\) into the general solution and read off \\(A\\) directly." }, { stepNumber: 6, description: "Substitute \\(t = 5\\).", workingLatex: "P(5) = 100 e^{0.1 \\times 5} = 100 e^{0.5} \\approx 164.87", explanation: "Numerically, \\(e^{0.5} \\approx 1.6487\\), so the population grows from \\(100\\) to about \\(165\\) in five time units." }, { stepNumber: 7, description: "Verify by substituting back into the DE.", workingLatex: "\\displaystyle\\frac{dP}{dt} = 100 \\cdot 0.1 \\, e^{0.1t} = 0.1 \\cdot \\left(100 e^{0.1t}\\right) = 0.1 P \\;\\checkmark", explanation: "Differentiating \\(P = 100e^{0.1t}\\) and comparing to \\(0.1P\\) gives an exact match, confirming the solution and the initial condition." } ], finalAnswer: "\\(P(5) = 100e^{0.5} \\approx 164.9\\)." } },
  // ── Exponential growth ────
  { id: "y2in10-002", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 02", difficulty: "Standard", questionText: "A bacterial colony grows so that \\(\\displaystyle\\frac{dN}{dt} = 0.3N\\). Find \\(N(t)\\) given \\(N(0) = 50\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dN}{dt} = 0.3 N", explanation: "Growth rate is proportional to current population with constant of proportionality \\(0.3\\); each bacterium contributes equally to the overall rate of increase." }, { stepNumber: 2, description: "Recognise as separable and separate.", workingLatex: "\\displaystyle\\frac{dN}{N} = 0.3\\,dt", explanation: "First-order separable ODE — \\(N\\)-terms to the left, \\(t\\)-terms to the right." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dN}{N} = \\displaystyle\\int 0.3\\,dt \\;\\;\\Rightarrow\\;\\; \\ln|N| = 0.3 t + C", explanation: "Standard log integral on the left; antiderivative of a constant on the right." }, { stepNumber: 4, description: "Solve explicitly for \\(N\\).", workingLatex: "N = A e^{0.3 t}, \\;\\; A = e^{C}", explanation: "Exponentiate; the integration constant is absorbed into the positive constant \\(A\\)." }, { stepNumber: 5, description: "Apply the initial condition \\(N(0) = 50\\).", workingLatex: "50 = A e^{0} \\;\\;\\Rightarrow\\;\\; A = 50", explanation: "Substituting \\(t = 0\\) fixes \\(A\\) immediately." }, { stepNumber: 6, description: "State the solution.", workingLatex: "N(t) = 50 e^{0.3 t}", explanation: "This is the explicit population function — every multiplicative increase of \\(e\\) takes time \\(1/0.3 \\approx 3.33\\) units." }, { stepNumber: 7, description: "Verify in the DE.", workingLatex: "\\displaystyle\\frac{dN}{dt} = 50 \\cdot 0.3 \\, e^{0.3t} = 0.3 N \\;\\checkmark", explanation: "Differentiating recovers the original DE exactly." } ], finalAnswer: "\\(N = 50e^{0.3t}\\)." } },
  { id: "y2in10-003", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 03", difficulty: "Standard", questionText: "For \\(P = P_0 e^{kt}\\), find the time for the population to double.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret 'double'.", workingLatex: "P(t) = 2 P_0", explanation: "The doubling time is the value of \\(t\\) at which the population is twice its initial value \\(P_0\\)." }, { stepNumber: 2, description: "Substitute into the solution.", workingLatex: "2 P_0 = P_0 e^{kt}", explanation: "Replace \\(P\\) with \\(2P_0\\) in the explicit solution." }, { stepNumber: 3, description: "Divide by \\(P_0\\).", workingLatex: "2 = e^{kt}", explanation: "Cancel the common factor \\(P_0 \\neq 0\\) to isolate the exponential." }, { stepNumber: 4, description: "Take natural logarithms.", workingLatex: "\\ln 2 = kt", explanation: "Applying \\(\\ln\\) brings the exponent down — this is the standard way to solve an exponential equation." }, { stepNumber: 5, description: "Solve for \\(t\\).", workingLatex: "t = \\displaystyle\\frac{\\ln 2}{k}", explanation: "Divide by \\(k\\). This is a famous formula: doubling time \\(=\\ln 2 / k\\) (and likewise half-life \\(=\\ln 2 / \\lambda\\) for decay)." } ], finalAnswer: "\\(t_{double} = \\displaystyle\\frac{\\ln 2}{k}\\)." } },
  { id: "y2in10-004", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 04", difficulty: "Standard", questionText: "Using \\(N = 50e^{0.3t}\\), find \\(t\\) when \\(N = 1000\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the equation.", workingLatex: "1000 = 50 e^{0.3 t}", explanation: "Substitute the target value \\(N = 1000\\) into the given solution." }, { stepNumber: 2, description: "Isolate the exponential.", workingLatex: "20 = e^{0.3 t}", explanation: "Divide both sides by \\(50\\); the ratio \\(1000/50 = 20\\) is the multiplicative factor the population must grow by." }, { stepNumber: 3, description: "Take natural logs.", workingLatex: "\\ln 20 = 0.3 t", explanation: "Applying \\(\\ln\\) removes the exponential and gives a linear equation in \\(t\\)." }, { stepNumber: 4, description: "Solve for \\(t\\).", workingLatex: "t = \\displaystyle\\frac{\\ln 20}{0.3}", explanation: "Divide by \\(0.3\\); this is the exact answer." }, { stepNumber: 5, description: "Evaluate numerically.", workingLatex: "t \\approx \\displaystyle\\frac{2.9957}{0.3} \\approx 9.986", explanation: "So the colony reaches \\(1000\\) bacteria after about ten time units." }, { stepNumber: 6, description: "Verify.", workingLatex: "50 \\cdot e^{0.3 \\times 9.986} = 50 \\cdot e^{2.996} \\approx 50 \\cdot 20.00 = 1000 \\;\\checkmark", explanation: "Substituting back into the solution recovers \\(N = 1000\\)." } ], finalAnswer: "\\(t = \\displaystyle\\frac{\\ln 20}{0.3} \\approx 9.99\\)." } },
  { id: "y2in10-005", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 05", difficulty: "Standard", questionText: "An investment grows continuously at rate 5% per annum. Find the value after 10 years if initial is £1000.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model physically.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 0.05 V", explanation: "'Continuous compounding at 5%' means the instantaneous rate of growth of \\(V\\) equals \\(0.05\\) times the current value." }, { stepNumber: 2, description: "Separate and integrate.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dV}{V} = \\displaystyle\\int 0.05\\,dt \\;\\;\\Rightarrow\\;\\; \\ln|V| = 0.05 t + C", explanation: "Standard separable approach: split variables and integrate." }, { stepNumber: 3, description: "Solve for \\(V\\).", workingLatex: "V = A e^{0.05 t}", explanation: "Exponentiate both sides; \\(A = e^{C}\\) is a positive constant absorbing \\(C\\)." }, { stepNumber: 4, description: "Apply the initial condition \\(V(0) = 1000\\).", workingLatex: "1000 = A \\;\\;\\Rightarrow\\;\\; V(t) = 1000 e^{0.05 t}", explanation: "Set \\(t = 0\\) and read off \\(A\\)." }, { stepNumber: 5, description: "Substitute \\(t = 10\\).", workingLatex: "V(10) = 1000 e^{0.05 \\times 10} = 1000 e^{0.5}", explanation: "Ten years' continuous growth at \\(5\\%\\) multiplies the initial investment by \\(e^{0.5}\\)." }, { stepNumber: 6, description: "Evaluate numerically.", workingLatex: "V(10) \\approx 1000 \\times 1.64872 \\approx \\pounds 1648.72", explanation: "Compare to discrete compounding: \\(1000(1.05)^{10} \\approx \\pounds 1628.89\\) — continuous compounding gives slightly more." }, { stepNumber: 7, description: "Verify in the DE.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 1000 \\cdot 0.05 \\, e^{0.05t} = 0.05 V \\;\\checkmark", explanation: "Differentiating reproduces the DE; the model is consistent." } ], finalAnswer: "\\(V \\approx £1648.72\\)." } },
  // ── Exponential decay ────
  { id: "y2in10-006", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 06", difficulty: "Standard", questionText: "A sample has \\(\\displaystyle\\frac{dN}{dt} = -0.002 N\\) (per year). If \\(N(0) = 1000\\), find \\(N(100)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the negative sign.", workingLatex: "\\displaystyle\\frac{dN}{dt} = -0.002 N", explanation: "The minus sign means the rate is negative whenever \\(N > 0\\) — the quantity decays. The decay constant is \\(\\lambda = 0.002\\) per year." }, { stepNumber: 2, description: "Separate and integrate.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dN}{N} = \\displaystyle\\int -0.002\\,dt \\;\\;\\Rightarrow\\;\\; \\ln|N| = -0.002 t + C", explanation: "Standard separable solve — variables on opposite sides, then integrate." }, { stepNumber: 3, description: "Exponentiate to solve for \\(N\\).", workingLatex: "N = A e^{-0.002 t}", explanation: "Lift both sides to \\(e^{(\\cdot)}\\); \\(A = e^{C}\\) is the integration constant." }, { stepNumber: 4, description: "Apply \\(N(0) = 1000\\).", workingLatex: "1000 = A \\;\\;\\Rightarrow\\;\\; N(t) = 1000 e^{-0.002 t}", explanation: "Substitute \\(t = 0\\) and pick off the constant." }, { stepNumber: 5, description: "Substitute \\(t = 100\\).", workingLatex: "N(100) = 1000 e^{-0.002 \\times 100} = 1000 e^{-0.2}", explanation: "The exponent is \\(-0.2\\); the sample has decayed by a factor of \\(e^{-0.2}\\)." }, { stepNumber: 6, description: "Evaluate.", workingLatex: "1000 \\times 0.8187 \\approx 818.73", explanation: "After \\(100\\) years roughly \\(81.9\\%\\) of the sample remains." }, { stepNumber: 7, description: "Verify in the DE.", workingLatex: "\\displaystyle\\frac{dN}{dt} = 1000 \\cdot (-0.002) e^{-0.002t} = -0.002 \\, N \\;\\checkmark", explanation: "Differentiating reproduces the original DE — solution confirmed." } ], finalAnswer: "\\(\\approx 818.7\\)." } },
  { id: "y2in10-007", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 07", difficulty: "Standard", questionText: "Derive the half-life for \\(\\displaystyle\\frac{dN}{dt} = -\\lambda N\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Solve the DE in general.", workingLatex: "\\displaystyle\\frac{dN}{N} = -\\lambda\\,dt \\;\\;\\Rightarrow\\;\\; \\ln|N| = -\\lambda t + C", explanation: "Separate variables and integrate — the standard recipe for exponential decay." }, { stepNumber: 2, description: "Express explicitly.", workingLatex: "N(t) = N_0 e^{-\\lambda t}, \\;\\; N_0 = N(0)", explanation: "Exponentiate and let \\(N_0\\) denote the initial amount, absorbing the integration constant." }, { stepNumber: 3, description: "Impose the half-life condition.", workingLatex: "N(t_{1/2}) = \\displaystyle\\frac{N_0}{2}", explanation: "By definition the half-life \\(t_{1/2}\\) is the time at which only half of the original quantity remains." }, { stepNumber: 4, description: "Substitute.", workingLatex: "\\displaystyle\\frac{N_0}{2} = N_0 e^{-\\lambda t_{1/2}} \\;\\;\\Rightarrow\\;\\; \\displaystyle\\frac{1}{2} = e^{-\\lambda t_{1/2}}", explanation: "Cancel \\(N_0\\); the half-life depends on \\(\\lambda\\) alone, not on \\(N_0\\)." }, { stepNumber: 5, description: "Take logs.", workingLatex: "-\\ln 2 = -\\lambda t_{1/2}", explanation: "Use \\(\\ln(1/2) = -\\ln 2\\)." }, { stepNumber: 6, description: "Solve.", workingLatex: "t_{1/2} = \\displaystyle\\frac{\\ln 2}{\\lambda}", explanation: "Divide through by \\(-\\lambda\\); the negatives cancel." } ], finalAnswer: "\\(t_{1/2} = \\displaystyle\\frac{\\ln 2}{\\lambda}\\)." } },
  { id: "y2in10-008", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 08", difficulty: "Standard", questionText: "A radioactive isotope has half-life 50 years. Find the decay constant.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Quote the half-life formula.", workingLatex: "t_{1/2} = \\displaystyle\\frac{\\ln 2}{\\lambda}", explanation: "Derived in the previous question. We now rearrange it for \\(\\lambda\\)." }, { stepNumber: 2, description: "Rearrange for \\(\\lambda\\).", workingLatex: "\\lambda = \\displaystyle\\frac{\\ln 2}{t_{1/2}}", explanation: "Multiply both sides by \\(\\lambda\\) then divide by \\(t_{1/2}\\)." }, { stepNumber: 3, description: "Substitute \\(t_{1/2} = 50\\).", workingLatex: "\\lambda = \\displaystyle\\frac{\\ln 2}{50}", explanation: "Direct substitution of the given half-life in years." }, { stepNumber: 4, description: "Evaluate numerically.", workingLatex: "\\lambda \\approx \\displaystyle\\frac{0.6931}{50} \\approx 0.01386 \\text{ year}^{-1}", explanation: "So about \\(1.39\\%\\) of the isotope decays per year." } ], finalAnswer: "\\(\\lambda = \\displaystyle\\frac{\\ln 2}{50} \\approx 0.01386\\)." } },
  { id: "y2in10-009", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 09", difficulty: "Challenge", questionText: "C-14 has half-life 5730 years. A sample has 25% of its original C-14. Find its age.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decay model.", workingLatex: "N(t) = N_0 e^{-\\lambda t}", explanation: "C-14 decays at a rate proportional to the amount present; the solution is exponential decay with constant \\(\\lambda\\)." }, { stepNumber: 2, description: "Relate \\(\\lambda\\) to the half-life.", workingLatex: "\\lambda = \\displaystyle\\frac{\\ln 2}{5730}", explanation: "From the half-life formula \\(t_{1/2} = \\ln 2 / \\lambda\\)." }, { stepNumber: 3, description: "Impose the 25% condition.", workingLatex: "0.25 N_0 = N_0 e^{-\\lambda t} \\;\\;\\Rightarrow\\;\\; \\displaystyle\\frac{1}{4} = e^{-\\lambda t}", explanation: "The sample now has a quarter of its original C-14, so the surviving fraction is \\(1/4\\)." }, { stepNumber: 4, description: "Take logs.", workingLatex: "-\\ln 4 = -\\lambda t \\;\\;\\Rightarrow\\;\\; t = \\displaystyle\\frac{\\ln 4}{\\lambda}", explanation: "Apply \\(\\ln\\) and rearrange. Using \\(\\ln 4 = 2\\ln 2\\) we get \\(t = \\displaystyle\\frac{2\\ln 2}{\\lambda} = 2 t_{1/2}\\)." }, { stepNumber: 5, description: "Substitute and evaluate.", workingLatex: "t = 2 \\times 5730 = 11460 \\text{ years}", explanation: "Each halving takes \\(5730\\) years, and we need two halvings (\\(1 \\to 1/2 \\to 1/4\\)). So the sample is \\(11\\,460\\) years old." }, { stepNumber: 6, description: "Verify.", workingLatex: "N(11460) = N_0 e^{-\\frac{\\ln 2}{5730} \\times 11460} = N_0 e^{-2\\ln 2} = \\displaystyle\\frac{N_0}{4} \\;\\checkmark", explanation: "Substituting back gives exactly \\(25\\%\\) of the original; the age is correct." } ], finalAnswer: "\\(t = 11460\\) years." } },
  // ── Newton's law of cooling ────
  { id: "y2in10-010", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 10", difficulty: "Standard", questionText: "Coffee at 80°C cools in a 20°C room according to \\(\\displaystyle\\frac{dT}{dt} = -k(T - 20)\\). Solve for \\(T(t)\\) given \\(T(0) = 80\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling", "Newton cooling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret Newton's law of cooling.", workingLatex: "\\displaystyle\\frac{dT}{dt} = -k(T - 20)", explanation: "The rate of cooling is proportional to the temperature excess above the room temperature \\(20^{\\circ}\\)C. Larger excess \\(\\Rightarrow\\) faster cooling. \\(k > 0\\) is the cooling constant." }, { stepNumber: 2, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dT}{T - 20} = -k\\,dt", explanation: "Group \\(T\\)-terms on one side and \\(t\\)-terms on the other — valid since \\(T \\neq 20\\) for hot coffee." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dT}{T - 20} = \\displaystyle\\int -k\\,dt \\;\\;\\Rightarrow\\;\\; \\ln|T - 20| = -k t + C", explanation: "Left integral is a logarithm (\\(f'/f\\) form with \\(f = T - 20\\)); right is linear in \\(t\\)." }, { stepNumber: 4, description: "Exponentiate.", workingLatex: "T - 20 = A e^{-k t}, \\;\\; A = e^{C}", explanation: "Lift to \\(e^{(\\cdot)}\\); drop the modulus because for hot coffee \\(T > 20\\) so the bracket stays positive." }, { stepNumber: 5, description: "Apply the initial condition \\(T(0) = 80\\).", workingLatex: "80 - 20 = A \\;\\;\\Rightarrow\\;\\; A = 60", explanation: "Substitute \\(t = 0\\): the initial temperature excess is \\(60^{\\circ}\\)C." }, { stepNumber: 6, description: "State the solution.", workingLatex: "T(t) = 20 + 60 e^{-k t}", explanation: "The coffee approaches room temperature \\(20^{\\circ}\\)C exponentially fast — the offset \\(60 e^{-kt}\\) dies away as \\(t \\to \\infty\\)." }, { stepNumber: 7, description: "Verify.", workingLatex: "\\displaystyle\\frac{dT}{dt} = -60 k \\, e^{-kt} = -k(T - 20) \\;\\checkmark", explanation: "Differentiating and substituting back into the DE gives an exact match." } ], finalAnswer: "\\(T = 20 + 60e^{-kt}\\)." } },
  { id: "y2in10-011", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 11", difficulty: "Standard", questionText: "If the coffee in the previous question is 50°C after 10 minutes, find \\(k\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the previous solution.", workingLatex: "T(t) = 20 + 60 e^{-k t}", explanation: "Carry forward the Newton's law solution and apply the new data point." }, { stepNumber: 2, description: "Substitute the data point.", workingLatex: "50 = 20 + 60 e^{-10 k}", explanation: "At \\(t = 10\\) min the coffee is at \\(50^{\\circ}\\)C." }, { stepNumber: 3, description: "Isolate the exponential.", workingLatex: "30 = 60 e^{-10 k} \\;\\;\\Rightarrow\\;\\; \\displaystyle\\frac{1}{2} = e^{-10 k}", explanation: "Subtract \\(20\\) then divide by \\(60\\): the coffee has cooled half-way to room temperature in ten minutes." }, { stepNumber: 4, description: "Take natural logs.", workingLatex: "-\\ln 2 = -10 k \\;\\;\\Rightarrow\\;\\; 10 k = \\ln 2", explanation: "Apply \\(\\ln\\) and use \\(\\ln(1/2) = -\\ln 2\\)." }, { stepNumber: 5, description: "Solve for \\(k\\).", workingLatex: "k = \\displaystyle\\frac{\\ln 2}{10}", explanation: "The exact value." }, { stepNumber: 6, description: "Evaluate numerically.", workingLatex: "k \\approx \\displaystyle\\frac{0.6931}{10} \\approx 0.0693 \\text{ min}^{-1}", explanation: "Per-minute cooling constant. Equivalently, the time-constant is \\(1/k \\approx 14.4\\) min." }, { stepNumber: 7, description: "Verify.", workingLatex: "T(10) = 20 + 60 e^{-\\ln 2} = 20 + 60 \\cdot \\displaystyle\\frac{1}{2} = 50 \\;\\checkmark", explanation: "Substituting the found \\(k\\) gives back the data point exactly." } ], finalAnswer: "\\(k = \\displaystyle\\frac{\\ln 2}{10} \\approx 0.0693\\)." } },
  { id: "y2in10-012", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 12", difficulty: "Standard", questionText: "Using the same model, find the time for the coffee to cool to 30°C.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Restate the solution with the known \\(k\\).", workingLatex: "T(t) = 20 + 60 e^{-k t}, \\;\\; k = \\displaystyle\\frac{\\ln 2}{10}", explanation: "From the previous two questions." }, { stepNumber: 2, description: "Set \\(T = 30\\).", workingLatex: "30 = 20 + 60 e^{-k t}", explanation: "Substitute the target temperature." }, { stepNumber: 3, description: "Isolate the exponential.", workingLatex: "10 = 60 e^{-k t} \\;\\;\\Rightarrow\\;\\; e^{-k t} = \\displaystyle\\frac{1}{6}", explanation: "Subtract \\(20\\), divide by \\(60\\)." }, { stepNumber: 4, description: "Take logs.", workingLatex: "-k t = -\\ln 6 \\;\\;\\Rightarrow\\;\\; t = \\displaystyle\\frac{\\ln 6}{k}", explanation: "Apply \\(\\ln\\), then divide by \\(k\\)." }, { stepNumber: 5, description: "Substitute \\(k\\).", workingLatex: "t = \\displaystyle\\frac{10 \\ln 6}{\\ln 2}", explanation: "Replace \\(k = \\ln 2 / 10\\); the \\(\\ln 2\\) ends up in the denominator." }, { stepNumber: 6, description: "Evaluate.", workingLatex: "t \\approx \\displaystyle\\frac{10 \\times 1.7918}{0.6931} \\approx 25.85 \\text{ min}", explanation: "So the coffee takes about \\(26\\) minutes to drop from \\(80^{\\circ}\\)C to \\(30^{\\circ}\\)C." } ], finalAnswer: "\\(t = \\displaystyle\\frac{\\ln 6}{k} \\approx 25.85\\) min." } },
  { id: "y2in10-013", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 13", difficulty: "Challenge", questionText: "A body cools from 37°C to 33°C in 1 hour, in a room at 25°C. Find the cooling constant \\(k\\) and the temperature 2 hours after the initial observation.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dT}{dt} = -k(T - 25), \\;\\; T(0) = 37", explanation: "Newton's law of cooling with ambient temperature \\(25^{\\circ}\\)C. Take \\(t = 0\\) to be the moment of the first observation, when the body is \\(37^{\\circ}\\)C." }, { stepNumber: 2, description: "Solve the DE in general form.", workingLatex: "T - 25 = A e^{-k t}", explanation: "Separable as in q10; let \\(A\\) be the constant of integration to be fixed by data." }, { stepNumber: 3, description: "Apply \\(T(0) = 37\\).", workingLatex: "37 - 25 = A \\;\\;\\Rightarrow\\;\\; A = 12 \\;\\;\\Rightarrow\\;\\; T(t) = 25 + 12 e^{-k t}", explanation: "The initial temperature excess above the room is \\(12^{\\circ}\\)C." }, { stepNumber: 4, description: "Apply \\(T(1) = 33\\) to find \\(k\\).", workingLatex: "33 = 25 + 12 e^{-k} \\;\\;\\Rightarrow\\;\\; 8 = 12 e^{-k} \\;\\;\\Rightarrow\\;\\; e^{-k} = \\displaystyle\\frac{2}{3}", explanation: "After one hour the excess has dropped from \\(12\\) to \\(8\\), i.e. by a factor \\(2/3\\)." }, { stepNumber: 5, description: "Take logs.", workingLatex: "k = -\\ln\\!\\left(\\displaystyle\\frac{2}{3}\\right) = \\ln\\!\\left(\\displaystyle\\frac{3}{2}\\right) \\approx 0.4055 \\text{ hr}^{-1}", explanation: "Use \\(-\\ln(2/3) = \\ln(3/2)\\)." }, { stepNumber: 6, description: "Predict \\(T\\) at \\(t = 2\\) hours.", workingLatex: "T(2) = 25 + 12 e^{-2k} = 25 + 12 \\!\\left(\\displaystyle\\frac{2}{3}\\right)^{2} = 25 + 12 \\cdot \\displaystyle\\frac{4}{9} = 25 + \\displaystyle\\frac{16}{3}", explanation: "Since \\(e^{-k} = 2/3\\), \\(e^{-2k} = (2/3)^{2} = 4/9\\). Multiply by the initial excess \\(12\\)." }, { stepNumber: 7, description: "Evaluate.", workingLatex: "T(2) = 25 + 5.333\\ldots \\approx 30.33^{\\circ}\\text{C}", explanation: "Two hours after the first observation the body has cooled to about \\(30.3^{\\circ}\\)C." }, { stepNumber: 8, description: "Verify the data points.", workingLatex: "T(0) = 25 + 12 = 37, \\;\\; T(1) = 25 + 12 \\cdot \\displaystyle\\frac{2}{3} = 33 \\;\\checkmark", explanation: "Both observations are reproduced exactly, confirming the model." } ], finalAnswer: "\\(k = \\ln(3/2) \\approx 0.405\\) hr\\(^{-1}\\); \\(T(2) = 25 + \\displaystyle\\frac{16}{3} \\approx 30.33^{\\circ}\\)C." } },
  // ── Falling objects ────
  { id: "y2in10-014", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 14", difficulty: "Foundation", questionText: "A falling object has \\(\\displaystyle\\frac{dv}{dt} = g\\). Find \\(v(t)\\) given \\(v(0) = 0\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dv}{dt} = g", explanation: "The only force on the object is gravity, giving constant acceleration \\(g\\) downward. No air resistance is included." }, { stepNumber: 2, description: "Integrate directly.", workingLatex: "v(t) = \\displaystyle\\int g\\,dt = g t + C", explanation: "Since the right-hand side has no \\(v\\)-dependence we can integrate immediately with respect to \\(t\\)." }, { stepNumber: 3, description: "Apply \\(v(0) = 0\\).", workingLatex: "0 = g \\cdot 0 + C \\;\\;\\Rightarrow\\;\\; C = 0", explanation: "The object starts from rest, so the constant of integration is zero." }, { stepNumber: 4, description: "State the solution.", workingLatex: "v(t) = g t", explanation: "Velocity grows linearly with time — the classic 'free-fall from rest' result." }, { stepNumber: 5, description: "Verify.", workingLatex: "\\displaystyle\\frac{d}{dt}(g t) = g \\;\\checkmark", explanation: "Differentiating recovers the DE, and \\(v(0) = 0\\) holds." } ], finalAnswer: "\\(v = gt\\)." } },
  { id: "y2in10-015", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 15", difficulty: "Challenge", questionText: "A falling object satisfies \\(\\displaystyle\\frac{dv}{dt} = g - kv\\). Solve for \\(v(t)\\) with \\(v(0) = 0\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the physics.", workingLatex: "\\displaystyle\\frac{dv}{dt} = g - k v", explanation: "Gravity drives the object down with acceleration \\(g\\); linear air resistance opposes motion with strength proportional to speed (coefficient \\(k > 0\\))." }, { stepNumber: 2, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dv}{g - k v} = dt", explanation: "Gather \\(v\\)-terms left and \\(t\\)-terms right — valid while \\(v < g/k\\) so the denominator is non-zero." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dv}{g - k v} = \\displaystyle\\int dt \\;\\;\\Rightarrow\\;\\; -\\displaystyle\\frac{1}{k} \\ln|g - k v| = t + C", explanation: "The left integral is a logarithm by reverse chain rule (derivative of \\(g - kv\\) is \\(-k\\); divide by \\(-k\\))." }, { stepNumber: 4, description: "Exponentiate.", workingLatex: "g - k v = A e^{-k t}, \\;\\; A = e^{-kC}", explanation: "Multiply both sides by \\(-k\\), then lift to \\(e^{(\\cdot)}\\); fold constants into a single \\(A\\)." }, { stepNumber: 5, description: "Apply \\(v(0) = 0\\).", workingLatex: "g - 0 = A \\;\\;\\Rightarrow\\;\\; A = g", explanation: "At \\(t = 0\\), the left-hand side is just \\(g\\)." }, { stepNumber: 6, description: "Solve for \\(v\\).", workingLatex: "g - k v = g e^{-k t} \\;\\;\\Rightarrow\\;\\; v(t) = \\displaystyle\\frac{g}{k}\\!\\left(1 - e^{-k t}\\right)", explanation: "Rearrange — the velocity rises from \\(0\\) and approaches the terminal speed \\(g/k\\)." }, { stepNumber: 7, description: "Interpret.", workingLatex: "v \\to \\displaystyle\\frac{g}{k} \\text{ as } t \\to \\infty", explanation: "Terminal velocity is reached when air drag exactly balances gravity (\\(kv = g\\))." }, { stepNumber: 8, description: "Verify.", workingLatex: "\\displaystyle\\frac{dv}{dt} = \\displaystyle\\frac{g}{k} \\cdot k \\, e^{-k t} = g e^{-k t} = g - k v \\;\\checkmark", explanation: "Differentiating the solution and substituting back gives exactly the original DE." } ], finalAnswer: "\\(v = \\displaystyle\\frac{g}{k}(1 - e^{-kt})\\)." } },
  { id: "y2in10-016", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 16", difficulty: "Standard", questionText: "From the previous model, find the terminal velocity.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret terminal velocity.", workingLatex: "v_{\\text{term}} = \\lim_{t \\to \\infty} v(t)", explanation: "It is the long-term speed at which acceleration is zero and the object falls steadily." }, { stepNumber: 2, description: "Take the limit in \\(v(t) = \\displaystyle\\frac{g}{k}(1 - e^{-k t})\\).", workingLatex: "v_{\\text{term}} = \\displaystyle\\frac{g}{k}\\!\\left(1 - 0\\right) = \\displaystyle\\frac{g}{k}", explanation: "Since \\(k > 0\\), \\(e^{-kt} \\to 0\\) as \\(t \\to \\infty\\)." }, { stepNumber: 3, description: "Alternative: set \\(\\displaystyle\\frac{dv}{dt} = 0\\) in the DE.", workingLatex: "0 = g - k v_{\\text{term}} \\;\\;\\Rightarrow\\;\\; v_{\\text{term}} = \\displaystyle\\frac{g}{k}", explanation: "Equilibrium of forces: gravity balances drag." }, { stepNumber: 4, description: "Physical meaning.", workingLatex: "v_{\\text{term}} = \\displaystyle\\frac{g}{k}", explanation: "Heavier objects (larger effective \\(g\\)-contribution) or less drag (smaller \\(k\\)) give higher terminal speeds." } ], finalAnswer: "\\(v_{term} = \\displaystyle\\frac{g}{k}\\)." } },
  // ── Tank problems ────
  { id: "y2in10-017", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 17", difficulty: "Challenge", questionText: "A tank drains with \\(\\displaystyle\\frac{dh}{dt} = -k\\sqrt h\\), \\(h(0) = 100\\). Find \\(h(t)\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model (Torricelli).", workingLatex: "\\displaystyle\\frac{dh}{dt} = -k\\sqrt{h}", explanation: "Outflow speed of water through a small hole is proportional to \\(\\sqrt{h}\\) (Torricelli's law), so the depth falls at a rate proportional to its square root." }, { stepNumber: 2, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dh}{\\sqrt{h}} = -k\\,dt \\;\\;\\Leftrightarrow\\;\\; h^{-1/2}\\,dh = -k\\,dt", explanation: "Move \\(h\\)-terms to the left; note \\(1/\\sqrt h = h^{-1/2}\\) for integration." }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int h^{-1/2}\\,dh = \\displaystyle\\int -k\\,dt \\;\\;\\Rightarrow\\;\\; 2 \\sqrt{h} = -k t + C", explanation: "Power rule: \\(\\int h^{-1/2}\\,dh = 2 h^{1/2}\\)." }, { stepNumber: 4, description: "Apply \\(h(0) = 100\\).", workingLatex: "2 \\sqrt{100} = C \\;\\;\\Rightarrow\\;\\; C = 20", explanation: "Substitute \\(t = 0, h = 100\\) and read off the constant." }, { stepNumber: 5, description: "Write the implicit solution.", workingLatex: "2\\sqrt{h} = 20 - k t", explanation: "Combine the previous two lines." }, { stepNumber: 6, description: "Solve explicitly for \\(h\\).", workingLatex: "\\sqrt{h} = 10 - \\displaystyle\\frac{k t}{2} \\;\\;\\Rightarrow\\;\\; h(t) = \\!\\left(10 - \\displaystyle\\frac{k t}{2}\\right)^{2}", explanation: "Divide by \\(2\\) then square. Valid while \\(10 - kt/2 \\ge 0\\), i.e. \\(t \\le 20/k\\)." }, { stepNumber: 7, description: "Interpret physically.", workingLatex: "h(t) = 0 \\text{ at } t = \\displaystyle\\frac{20}{k}", explanation: "The tank empties in finite time \\(t^{*} = 20/k\\), after which the model no longer applies." }, { stepNumber: 8, description: "Verify in the DE.", workingLatex: "\\displaystyle\\frac{dh}{dt} = 2\\!\\left(10 - \\displaystyle\\frac{k t}{2}\\right)\\!\\cdot\\!\\left(-\\displaystyle\\frac{k}{2}\\right) = -k\\!\\left(10 - \\displaystyle\\frac{k t}{2}\\right) = -k\\sqrt{h} \\;\\checkmark", explanation: "Differentiating the squared expression and using \\(\\sqrt{h} = 10 - kt/2\\) reproduces the original DE." } ], finalAnswer: "\\(h(t) = \\left(10 - \\displaystyle\\frac{kt}{2}\\right)^2\\)." } },
  { id: "y2in10-018", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 18", difficulty: "Standard", questionText: "Using the previous model, find the time at which \\(h = 0\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Use the previous solution.", workingLatex: "h(t) = \\!\\left(10 - \\displaystyle\\frac{k t}{2}\\right)^{2}", explanation: "Carry forward from q17." }, { stepNumber: 2, description: "Set \\(h = 0\\).", workingLatex: "\\!\\left(10 - \\displaystyle\\frac{k t}{2}\\right)^{2} = 0 \\;\\;\\Rightarrow\\;\\; 10 - \\displaystyle\\frac{k t}{2} = 0", explanation: "A square is zero only when its base is zero." }, { stepNumber: 3, description: "Solve for \\(t\\).", workingLatex: "\\displaystyle\\frac{k t}{2} = 10 \\;\\;\\Rightarrow\\;\\; t = \\displaystyle\\frac{20}{k}", explanation: "Multiply by \\(2/k\\)." }, { stepNumber: 4, description: "Interpret.", workingLatex: "t_{\\text{empty}} = \\displaystyle\\frac{20}{k}", explanation: "The tank drains in finite time — a characteristic feature of Torricelli-type outflow (unlike exponential decay, which never quite reaches zero)." } ], finalAnswer: "\\(t = \\displaystyle\\frac{20}{k}\\)." } },
  { id: "y2in10-019", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 19", difficulty: "Challenge", questionText: "Water flows in at 5 L/s and out proportionally: \\(\\displaystyle\\frac{dV}{dt} = 5 - 0.1V\\), \\(V(0) = 0\\). Solve.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 5 - 0.1 V", explanation: "Constant inflow rate \\(5\\) L/s and an outflow rate that grows linearly with the amount of water present (coefficient \\(0.1\\) per s)." }, { stepNumber: 2, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dV}{5 - 0.1 V} = dt", explanation: "Valid while \\(V < 50\\); after that the inflow no longer exceeds outflow." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dV}{5 - 0.1 V} = \\displaystyle\\int dt \\;\\;\\Rightarrow\\;\\; -10 \\ln|5 - 0.1 V| = t + C", explanation: "Reverse chain rule: the derivative of \\(5 - 0.1 V\\) is \\(-0.1\\), so dividing by \\(-0.1\\) gives the factor \\(-10\\)." }, { stepNumber: 4, description: "Apply \\(V(0) = 0\\).", workingLatex: "-10 \\ln 5 = C", explanation: "Substitute \\(t = 0, V = 0\\) to find \\(C = -10 \\ln 5\\)." }, { stepNumber: 5, description: "Combine and exponentiate.", workingLatex: "-10 \\ln|5 - 0.1 V| = t - 10 \\ln 5 \\;\\;\\Rightarrow\\;\\; \\ln\\!\\left|\\displaystyle\\frac{5 - 0.1 V}{5}\\right| = -\\displaystyle\\frac{t}{10}", explanation: "Move the constant across and divide by \\(-10\\); use \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 6, description: "Solve for \\(V\\).", workingLatex: "\\displaystyle\\frac{5 - 0.1 V}{5} = e^{-t/10} \\;\\;\\Rightarrow\\;\\; 5 - 0.1 V = 5 e^{-0.1 t} \\;\\;\\Rightarrow\\;\\; V(t) = 50\\!\\left(1 - e^{-0.1 t}\\right)", explanation: "Lift to \\(e^{(\\cdot)}\\), then isolate \\(V\\)." }, { stepNumber: 7, description: "Interpret.", workingLatex: "V \\to 50 \\text{ L as } t \\to \\infty", explanation: "The tank fills towards a steady-state volume of \\(50\\) L, where inflow exactly balances outflow." }, { stepNumber: 8, description: "Verify.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 50 \\cdot 0.1 \\, e^{-0.1 t} = 5 e^{-0.1 t} = 5 - 0.1 V \\;\\checkmark", explanation: "Differentiation reproduces the DE." } ], finalAnswer: "\\(V = 50(1 - e^{-0.1t})\\)." } },
  { id: "y2in10-020", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 20", difficulty: "Foundation", questionText: "Find the steady state of the tank in q19.", marks: 1, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Definition of steady state.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 0", explanation: "At steady state the volume stops changing." }, { stepNumber: 2, description: "Substitute into the DE.", workingLatex: "0 = 5 - 0.1 V_{\\ast}", explanation: "Use the DE \\(\\displaystyle\\frac{dV}{dt} = 5 - 0.1V\\) with the time derivative set to zero." }, { stepNumber: 3, description: "Solve.", workingLatex: "V_{\\ast} = \\displaystyle\\frac{5}{0.1} = 50 \\text{ L}", explanation: "Divide \\(5\\) by \\(0.1\\)." }, { stepNumber: 4, description: "Consistency check.", workingLatex: "\\lim_{t \\to \\infty} 50\\!\\left(1 - e^{-0.1 t}\\right) = 50 \\;\\checkmark", explanation: "Matches the long-term behaviour of the explicit solution from q19." } ], finalAnswer: "\\(V = 50\\) L." } },
  // ── Logistic ────
  { id: "y2in10-021", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 21", difficulty: "Challenge", questionText: "Solve the logistic DE \\(\\displaystyle\\frac{dP}{dt} = 0.01P(1000 - P)\\) with \\(P(0) = 100\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the logistic model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = 0.01 P (1000 - P)", explanation: "Population grows fast when \\(P\\) is small but slows as \\(P\\) nears the carrying capacity \\(M = 1000\\); at \\(P = 1000\\) the rate is zero." }, { stepNumber: 2, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dP}{P(1000 - P)} = 0.01\\,dt", explanation: "Valid for \\(0 < P < 1000\\)." }, { stepNumber: 3, description: "Partial fractions.", workingLatex: "\\displaystyle\\frac{1}{P(1000 - P)} = \\displaystyle\\frac{1}{1000}\\!\\left(\\displaystyle\\frac{1}{P} + \\displaystyle\\frac{1}{1000 - P}\\right)", explanation: "Standard decomposition: \\(1 = (1000 - P) \\cdot A + P \\cdot B\\); setting \\(P = 0, 1000\\) gives \\(A = B = 1/1000\\)." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\frac{1}{1000}\\!\\left(\\ln|P| - \\ln|1000 - P|\\right) = 0.01 t + C", explanation: "Integrate term-by-term; the minus sign in front of the second log comes from the chain factor in \\(\\int \\displaystyle\\frac{-1}{1000 - P}\\,dP = -(-\\ln|1000 - P|)\\) — wait — direct: \\(\\int \\displaystyle\\frac{1}{1000 - P}\\,dP = -\\ln|1000 - P|\\). Combine to a single log of a ratio." }, { stepNumber: 5, description: "Combine logs and apply IC.", workingLatex: "\\displaystyle\\frac{1}{1000}\\ln\\!\\left|\\displaystyle\\frac{P}{1000 - P}\\right| = 0.01 t + C", explanation: "Compress using \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 6, description: "Use \\(P(0) = 100\\) to find \\(C\\).", workingLatex: "\\displaystyle\\frac{1}{1000}\\ln\\!\\left(\\displaystyle\\frac{100}{900}\\right) = C \\;\\;\\Rightarrow\\;\\; C = \\displaystyle\\frac{1}{1000}\\ln\\!\\left(\\displaystyle\\frac{1}{9}\\right)", explanation: "Substitute \\(t = 0, P = 100\\); then \\(100/(1000 - 100) = 1/9\\)." }, { stepNumber: 7, description: "Combine and rearrange.", workingLatex: "\\ln\\!\\left(\\displaystyle\\frac{P}{1000 - P}\\right) - \\ln\\!\\left(\\displaystyle\\frac{1}{9}\\right) = 10 t \\;\\;\\Rightarrow\\;\\; \\displaystyle\\frac{P}{1000 - P} = \\displaystyle\\frac{1}{9} e^{10 t}", explanation: "Multiply by \\(1000\\), exponentiate, and merge constants." }, { stepNumber: 8, description: "Solve explicitly for \\(P\\).", workingLatex: "9 P = (1000 - P) e^{10 t} \\;\\;\\Rightarrow\\;\\; P\\!\\left(9 + e^{10 t}\\right) = 1000 e^{10 t} \\;\\;\\Rightarrow\\;\\; P(t) = \\displaystyle\\frac{1000}{1 + 9 e^{-10 t}}", explanation: "Cross-multiply, gather \\(P\\) on one side and divide; finally multiply top and bottom by \\(e^{-10t}\\)." }, { stepNumber: 9, description: "Verify limits.", workingLatex: "P(0) = \\displaystyle\\frac{1000}{1 + 9} = 100 \\;\\checkmark, \\;\\; \\lim_{t \\to \\infty} P(t) = 1000", explanation: "Initial condition holds and the carrying capacity \\(1000\\) is approached." } ], finalAnswer: "\\(P(t) = \\displaystyle\\frac{1000}{1 + 9e^{-10t}}\\)." } },
  { id: "y2in10-022", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 22", difficulty: "Foundation", questionText: "What is the carrying capacity in \\(\\displaystyle\\frac{dP}{dt} = 0.01P(1000 - P)\\)?", marks: 1, examStyle: false, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Definition.", workingLatex: "\\text{Carrying capacity} = \\text{the nonzero } P \\text{ where } \\displaystyle\\frac{dP}{dt} = 0", explanation: "A stable equilibrium population in the logistic model." }, { stepNumber: 2, description: "Set the RHS to zero.", workingLatex: "0.01 P (1000 - P) = 0 \\;\\;\\Rightarrow\\;\\; P = 0 \\text{ or } P = 1000", explanation: "The product is zero exactly when one of the factors is zero." }, { stepNumber: 3, description: "Choose the nonzero, stable root.", workingLatex: "P = 1000", explanation: "Carrying capacity is the upper equilibrium; \\(P = 0\\) is the (unstable) extinction state." }, { stepNumber: 4, description: "Confirm interpretation.", workingLatex: "M = 1000", explanation: "Long-term population settles to \\(1000\\), as seen in q21's explicit solution." } ], finalAnswer: "1000." } },
  { id: "y2in10-023", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 23", difficulty: "Standard", questionText: "In a logistic model \\(\\displaystyle\\frac{dP}{dt} = kP(M - P)\\), at what value of \\(P\\) is the rate of growth maximum?", marks: 3, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Treat the growth rate as a function of \\(P\\).", workingLatex: "R(P) = k P (M - P)", explanation: "We want to maximise this with respect to \\(P\\), keeping \\(k\\) and \\(M\\) fixed." }, { stepNumber: 2, description: "Expand and differentiate.", workingLatex: "R(P) = k M P - k P^{2} \\;\\;\\Rightarrow\\;\\; \\displaystyle\\frac{dR}{dP} = k M - 2 k P", explanation: "Standard polynomial differentiation in \\(P\\)." }, { stepNumber: 3, description: "Set the derivative to zero.", workingLatex: "k M - 2 k P = 0 \\;\\;\\Rightarrow\\;\\; P = \\displaystyle\\frac{M}{2}", explanation: "Critical point of the growth-rate function." }, { stepNumber: 4, description: "Second-derivative test.", workingLatex: "\\displaystyle\\frac{d^{2} R}{dP^{2}} = -2 k < 0", explanation: "Negative, so \\(P = M/2\\) is a maximum." }, { stepNumber: 5, description: "State the maximum rate.", workingLatex: "R_{\\max} = k \\cdot \\displaystyle\\frac{M}{2} \\cdot \\displaystyle\\frac{M}{2} = \\displaystyle\\frac{k M^{2}}{4}", explanation: "Substitute back. Geometrically this is the inflection point of the logistic curve — the steepest part of \\(P(t)\\)." }, { stepNumber: 6, description: "Interpret.", workingLatex: "P_{\\text{max growth}} = \\displaystyle\\frac{M}{2}", explanation: "The population grows fastest exactly when it is at half its carrying capacity." } ], finalAnswer: "\\(P = \\displaystyle\\frac{M}{2}\\)." } },
  // ── Mixing problems ────
  { id: "y2in10-024", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 24", difficulty: "Challenge", questionText: "A tank of 100 L has pure water. Brine (10 g/L) flows in at 2 L/min, and mixture out at 2 L/min. Set up and solve a DE for salt amount \\(S(t)\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["mixing"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model and compute rates.", workingLatex: "\\text{Rate in} = 10\\,\\text{g/L} \\times 2\\,\\text{L/min} = 20\\,\\text{g/min}", explanation: "Brine enters at \\(2\\) L/min with concentration \\(10\\) g/L, delivering \\(20\\) g of salt every minute." }, { stepNumber: 2, description: "Outflow rate of salt.", workingLatex: "\\text{Rate out} = \\displaystyle\\frac{S}{100}\\,\\text{g/L} \\times 2\\,\\text{L/min} = \\displaystyle\\frac{S}{50}\\,\\text{g/min}", explanation: "Tank volume stays constant at \\(100\\) L (inflow = outflow), so the concentration in the well-mixed tank is \\(S/100\\) g/L, and salt leaves at \\(2(S/100) = S/50\\) g/min." }, { stepNumber: 3, description: "Write the DE.", workingLatex: "\\displaystyle\\frac{dS}{dt} = 20 - \\displaystyle\\frac{S}{50}", explanation: "Net rate of change of salt = rate in minus rate out — a first-order linear ODE." }, { stepNumber: 4, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dS}{20 - \\displaystyle\\frac{S}{50}} = dt \\;\\;\\Leftrightarrow\\;\\; \\displaystyle\\frac{50\\,dS}{1000 - S} = dt", explanation: "Multiply top and bottom of the LHS by \\(50\\) to clear the fraction inside the denominator." }, { stepNumber: 5, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{50\\,dS}{1000 - S} = \\displaystyle\\int dt \\;\\;\\Rightarrow\\;\\; -50 \\ln|1000 - S| = t + C", explanation: "Reverse chain rule with \\(f = 1000 - S, f' = -1\\): \\(\\int \\displaystyle\\frac{dS}{1000 - S} = -\\ln|1000 - S|\\)." }, { stepNumber: 6, description: "Apply the initial condition \\(S(0) = 0\\) (pure water).", workingLatex: "-50 \\ln 1000 = C", explanation: "Substitute \\(t = 0, S = 0\\) and read off \\(C\\)." }, { stepNumber: 7, description: "Combine and exponentiate.", workingLatex: "-50 \\ln(1000 - S) = t - 50 \\ln 1000 \\;\\;\\Rightarrow\\;\\; \\ln\\!\\left(\\displaystyle\\frac{1000 - S}{1000}\\right) = -\\displaystyle\\frac{t}{50}", explanation: "Move the constant across and divide by \\(-50\\); use the log-ratio rule." }, { stepNumber: 8, description: "Solve for \\(S\\).", workingLatex: "1000 - S = 1000 e^{-t/50} \\;\\;\\Rightarrow\\;\\; S(t) = 1000\\!\\left(1 - e^{-t/50}\\right) \\text{ g}", explanation: "Lift to \\(e^{(\\cdot)}\\), then rearrange. Salt content rises from \\(0\\) and approaches the steady-state value \\(1000\\) g (which corresponds to the inflow concentration of \\(10\\) g/L times \\(100\\) L)." }, { stepNumber: 9, description: "Verify in the DE.", workingLatex: "\\displaystyle\\frac{dS}{dt} = 1000 \\cdot \\displaystyle\\frac{1}{50} e^{-t/50} = 20 e^{-t/50} = 20 - 20\\!\\left(1 - e^{-t/50}\\right) = 20 - \\displaystyle\\frac{S}{50} \\;\\checkmark", explanation: "Differentiate the solution and substitute back: it recovers the DE exactly." } ], finalAnswer: "\\(S(t) = 1000(1 - e^{-t/50})\\) grams." } },
  { id: "y2in10-025", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 25", difficulty: "Standard", questionText: "Using the previous model, find the time for \\(S = 500\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["mixing"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the model.", workingLatex: "S(t) = 1000\\left(1 - e^{-t/50}\\right)", explanation: "This is the solution of the mixing DE from the previous question. \\(S\\) grows from \\(0\\) toward the equilibrium value \\(1000\\) g, which is the salt content the tank would hold if the brine flowed in forever." }, { stepNumber: 2, description: "Set \\(S = 500\\) and isolate the exponential.", workingLatex: "500 = 1000\\left(1 - e^{-t/50}\\right) \\;\\Rightarrow\\; 1 - e^{-t/50} = \\displaystyle\\frac{1}{2}", explanation: "We want the half-saturation time — the moment the salt amount reaches half of its long-run value. Dividing both sides by the equilibrium constant \\(1000\\) cleans things up." }, { stepNumber: 3, description: "Solve for the exponential.", workingLatex: "e^{-t/50} = \\displaystyle\\frac{1}{2}", explanation: "Subtracting from \\(1\\) extracts the exponential term on its own. Half of the journey to equilibrium has been completed when the exponential decay factor is also at one-half." }, { stepNumber: 4, description: "Take logs and solve for \\(t\\).", workingLatex: "-\\displaystyle\\frac{t}{50} = \\ln\\!\\left(\\displaystyle\\frac{1}{2}\\right) = -\\ln 2 \\;\\Rightarrow\\; t = 50\\ln 2", explanation: "Apply \\(\\ln\\) to both sides and use \\(\\ln(1/2) = -\\ln 2\\). The minus signs cancel, giving a clean closed form." }, { stepNumber: 5, description: "Evaluate numerically.", workingLatex: "t = 50\\ln 2 \\approx 50 \\times 0.69315 \\approx 34.66\\text{ min}", explanation: "About 34 min 40 s — the tank is at half its equilibrium salt level after roughly the system time-constant \\(\\tau = 50\\) min scaled by \\(\\ln 2\\). This matches the familiar 'half-life' of a first-order approach to equilibrium." }, { stepNumber: 6, description: "Verification.", workingLatex: "S(50\\ln 2) = 1000\\left(1 - e^{-\\ln 2}\\right) = 1000\\left(1 - \\displaystyle\\frac{1}{2}\\right) = 500\\;\\checkmark", explanation: "Substituting back recovers \\(S = 500\\) g exactly — the closed form is consistent with the requirement." } ], finalAnswer: "\\(t = 50\\ln 2 \\approx 34.66\\) min." } },
  // ── Growth/decay word problems ────
  { id: "y2in10-026", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 26", difficulty: "Challenge", questionText: "For a second-order reaction, \\(\\displaystyle\\frac{dC}{dt} = -kC^2\\) with \\(C(0) = C_0\\). Solve.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["chemistry"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dC}{dt} = -kC^2", explanation: "The rate of disappearance of the reactant is proportional to the square of its own concentration — characteristic of a single-species second-order reaction. Both \\(C\\) and \\(k\\) are positive, so \\(dC/dt < 0\\) and the concentration decays." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Separable nonlinear ODE in } C.", explanation: "The right-hand side factors cleanly as \\(g(t)\\,h(C) = (-k)\\cdot C^2\\), so the standard separation-of-variables routine applies." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dC}{C^2} = -k\\,dt", explanation: "Divide both sides by \\(C^2\\) (legitimate while \\(C > 0\\)) and multiply by \\(dt\\). All the \\(C\\) terms now sit on the left and all the \\(t\\) terms on the right." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int C^{-2}\\,dC = \\displaystyle\\int -k\\,dt \\;\\Rightarrow\\; -\\displaystyle\\frac{1}{C} = -kt + A", explanation: "Power rule with \\(n = -2\\) gives \\(C^{-1}/(-1) = -1/C\\). On the right, \\(-k\\) is constant in \\(t\\), integrating to \\(-kt\\). One constant of integration \\(A\\) suffices." }, { stepNumber: 5, description: "Apply the initial condition \\(C(0) = C_0\\).", workingLatex: "-\\displaystyle\\frac{1}{C_0} = 0 + A \\;\\Rightarrow\\; A = -\\displaystyle\\frac{1}{C_0}", explanation: "Substituting \\(t = 0\\), \\(C = C_0\\) pins down \\(A\\) immediately. The constant carries the memory of the starting concentration." }, { stepNumber: 6, description: "Solve for \\(C(t)\\) explicitly.", workingLatex: "-\\displaystyle\\frac{1}{C} = -kt - \\displaystyle\\frac{1}{C_0} \\;\\Rightarrow\\; \\displaystyle\\frac{1}{C} = kt + \\displaystyle\\frac{1}{C_0} = \\displaystyle\\frac{1 + C_0 kt}{C_0}", explanation: "Multiply through by \\(-1\\) and place over a common denominator. The reciprocal form \\(1/C\\) is linear in \\(t\\) — a useful diagnostic for second-order kinetics in chemistry." }, { stepNumber: 7, description: "Invert to obtain \\(C\\).", workingLatex: "C(t) = \\displaystyle\\frac{C_0}{1 + C_0 kt}", explanation: "Take reciprocals. The denominator grows linearly with \\(t\\), so \\(C(t)\\) decays — but more slowly than the first-order exponential decay." }, { stepNumber: 8, description: "Verification.", workingLatex: "\\displaystyle\\frac{dC}{dt} = -\\displaystyle\\frac{C_0^2 k}{(1 + C_0 kt)^2} = -k\\left(\\displaystyle\\frac{C_0}{1 + C_0 kt}\\right)^2 = -kC^2\\;\\checkmark", explanation: "Differentiating the closed form recovers the original DE exactly. Also \\(C(0) = C_0/(1+0) = C_0\\), matching the initial condition." } ], finalAnswer: "\\(C(t) = \\displaystyle\\frac{C_0}{1 + C_0 kt}\\)." } },
  { id: "y2in10-027", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 27", difficulty: "Challenge", questionText: "In a town of 1000 people, the rate a rumour spreads satisfies \\(\\displaystyle\\frac{dN}{dt} = 0.002N(1000 - N)\\). Solve with \\(N(0) = 10\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dN}{dt} = 0.002\\,N\\,(1000 - N)", explanation: "The spread rate is proportional to both the number who know (\\(N\\)) and those who don't (\\(1000 - N\\)). This is the classic logistic equation with carrying capacity \\(M = 1000\\) and intrinsic rate \\(r = kM = 0.002\\times 1000 = 2\\)." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Separable; logistic with } M = 1000, \\;r = 2.", explanation: "Rewriting as \\(dN/dt = 2N(1 - N/1000)\\) puts it in standard logistic form. The general solution shape is \\(N = M/(1 + Ae^{-rt})\\)." }, { stepNumber: 3, description: "Separate using partial fractions.", workingLatex: "\\displaystyle\\frac{1}{N(1000 - N)} = \\displaystyle\\frac{1}{1000}\\!\\left(\\displaystyle\\frac{1}{N} + \\displaystyle\\frac{1}{1000 - N}\\right)", explanation: "Decompose to split the bilinear denominator into two simple logs. Then \\(\\displaystyle\\frac{dN}{N(1000-N)} = 0.002\\,dt\\)." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\frac{1}{1000}\\left[\\ln|N| - \\ln|1000 - N|\\right] = 0.002t + A \\;\\Rightarrow\\; \\ln\\!\\left(\\displaystyle\\frac{N}{1000 - N}\\right) = 2t + B", explanation: "Multiply through by \\(1000\\) and combine the two logs into a single ratio. \\(B = 1000A\\) is just a renamed constant." }, { stepNumber: 5, description: "Apply the initial condition \\(N(0) = 10\\).", workingLatex: "\\ln\\!\\left(\\displaystyle\\frac{10}{990}\\right) = B \\;\\Rightarrow\\; B = -\\ln 99", explanation: "Substituting \\(t = 0, N = 10\\) into the log equation. Note \\(10/990 = 1/99\\), so \\(B = \\ln(1/99) = -\\ln 99\\)." }, { stepNumber: 6, description: "Exponentiate to remove the log.", workingLatex: "\\displaystyle\\frac{N}{1000 - N} = e^{2t - \\ln 99} = \\displaystyle\\frac{e^{2t}}{99}", explanation: "Exponentiating both sides converts the log equation into a clean algebraic relation between \\(N\\) and \\(t\\)." }, { stepNumber: 7, description: "Solve for \\(N\\) explicitly.", workingLatex: "99N = (1000 - N)e^{2t} \\;\\Rightarrow\\; N(99 + e^{2t}) = 1000\\,e^{2t} \\;\\Rightarrow\\; N = \\displaystyle\\frac{1000}{1 + 99e^{-2t}}", explanation: "Cross-multiply, collect the \\(N\\) terms, then divide through by \\(e^{2t}\\) (top and bottom) to get the standard logistic form \\(M/(1 + Ae^{-rt})\\) with \\(A = 99\\)." }, { stepNumber: 8, description: "Verification.", workingLatex: "N(0) = \\displaystyle\\frac{1000}{1 + 99} = 10\\;\\checkmark \\quad\\text{and}\\quad \\lim_{t \\to \\infty} N(t) = 1000.", explanation: "The IC is recovered and the carrying capacity is approached asymptotically — exactly the expected logistic behaviour." } ], finalAnswer: "\\(N(t) = \\displaystyle\\frac{1000}{1 + 99e^{-2t}}\\)." } },
  { id: "y2in10-028", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 28", difficulty: "Standard", questionText: "Using the previous model, find the time when \\(N = 500\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the model.", workingLatex: "N(t) = \\displaystyle\\frac{1000}{1 + 99e^{-2t}}", explanation: "\\(N = 500\\) is the halfway point of the logistic curve — exactly half the carrying capacity \\(M = 1000\\). This is also where the rumour spreads fastest (the inflection point)." }, { stepNumber: 2, description: "Set \\(N = 500\\) and isolate the denominator.", workingLatex: "500 = \\displaystyle\\frac{1000}{1 + 99e^{-2t}} \\;\\Rightarrow\\; 1 + 99e^{-2t} = 2", explanation: "Multiply both sides by the denominator and divide by 500. The equation reduces to a single exponential to solve." }, { stepNumber: 3, description: "Solve for the exponential.", workingLatex: "99e^{-2t} = 1 \\;\\Rightarrow\\; e^{-2t} = \\displaystyle\\frac{1}{99}", explanation: "Subtract \\(1\\) and divide by \\(99\\). The exponential factor at the inflection is the reciprocal of \\(A = 99\\), as expected." }, { stepNumber: 4, description: "Take logs.", workingLatex: "-2t = \\ln\\!\\left(\\displaystyle\\frac{1}{99}\\right) = -\\ln 99 \\;\\Rightarrow\\; t = \\displaystyle\\frac{\\ln 99}{2}", explanation: "Take \\(\\ln\\) of both sides. The signs cancel to give a clean closed form for the inflection time." }, { stepNumber: 5, description: "Evaluate numerically.", workingLatex: "t = \\displaystyle\\frac{\\ln 99}{2} \\approx \\displaystyle\\frac{4.5951}{2} \\approx 2.298\\text{ time units}", explanation: "Roughly \\(2.3\\) time units after the rumour starts, half the town has heard it. From this point on, the rate of new tellings begins to slow." }, { stepNumber: 6, description: "Verification.", workingLatex: "N\\!\\left(\\displaystyle\\frac{\\ln 99}{2}\\right) = \\displaystyle\\frac{1000}{1 + 99 \\cdot e^{-\\ln 99}} = \\displaystyle\\frac{1000}{1 + 1} = 500\\;\\checkmark", explanation: "Plugging back confirms \\(N = 500\\) exactly. The closed form is consistent." } ], finalAnswer: "\\(t = \\displaystyle\\frac{\\ln 99}{2} \\approx 2.30\\) (time units)." } },
  { id: "y2in10-029", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 29", difficulty: "Challenge", questionText: "Drug enters bloodstream at rate \\(r = 5\\) (mg/hr) and is eliminated: \\(\\displaystyle\\frac{dC}{dt} = -0.1C + 5\\), \\(C(0) = 0\\). Solve.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dC}{dt} = -0.1C + 5", explanation: "Two competing processes: continuous infusion adds \\(5\\) mg/hr to the bloodstream, while first-order elimination removes a fixed fraction (\\(10\\%\\)) of the current amount each hour. The signs reflect this — infusion positive, clearance negative." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Linear first-order, separable about the equilibrium.}", explanation: "Setting \\(dC/dt = 0\\) gives the steady state \\(C^* = 50\\). Substituting \\(u = C - 50\\) reduces the DE to \\(du/dt = -0.1u\\), a pure exponential decay equation." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dC}{5 - 0.1C} = dt", explanation: "Rearrange \\(dC/dt = 5 - 0.1C\\) by dividing both sides by \\((5 - 0.1C)\\) (valid as long as \\(C \\neq 50\\)). All \\(C\\) on the left, all \\(t\\) on the right." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dC}{5 - 0.1C} = \\displaystyle\\int dt \\;\\Rightarrow\\; -\\displaystyle\\frac{1}{0.1}\\ln|5 - 0.1C| = t + A", explanation: "Reverse-chain rule with \\(f(C) = 5 - 0.1C\\), \\(f'(C) = -0.1\\): the integral picks up a factor of \\(-1/0.1 = -10\\). Hence \\(-10\\ln|5 - 0.1C| = t + A\\)." }, { stepNumber: 5, description: "Apply the initial condition \\(C(0) = 0\\).", workingLatex: "-10\\ln|5 - 0| = 0 + A \\;\\Rightarrow\\; A = -10\\ln 5", explanation: "Substituting \\(t = 0, C = 0\\) fixes the constant. The starting value enters the constant of integration." }, { stepNumber: 6, description: "Solve for \\(C\\) explicitly.", workingLatex: "-10\\ln|5 - 0.1C| = t - 10\\ln 5 \\;\\Rightarrow\\; \\ln\\!\\left|\\displaystyle\\frac{5 - 0.1C}{5}\\right| = -\\displaystyle\\frac{t}{10}", explanation: "Move the constant across and divide through by \\(-10\\). Combine the two logs into a single log of a ratio." }, { stepNumber: 7, description: "Exponentiate and rearrange.", workingLatex: "5 - 0.1C = 5e^{-0.1t} \\;\\Rightarrow\\; C(t) = 50\\left(1 - e^{-0.1t}\\right)", explanation: "Exponentiate, then multiply through by \\(10\\). The result has the classic 'rise to equilibrium' shape: \\(C\\) climbs monotonically from \\(0\\) toward the steady-state value \\(50\\) mg." }, { stepNumber: 8, description: "Verification.", workingLatex: "C(0) = 50(1 - 1) = 0\\;\\checkmark \\quad\\text{and}\\quad \\displaystyle\\frac{dC}{dt} = 5e^{-0.1t} = 5 - 0.1\\cdot 50(1 - e^{-0.1t}) = 5 - 0.1C\\;\\checkmark", explanation: "Both the IC and the DE are satisfied identically — the closed-form solution is correct." } ], finalAnswer: "\\(C(t) = 50\\left(1 - e^{-0.1t}\\right)\\) mg." } },
  { id: "y2in10-030", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 30", difficulty: "Foundation", questionText: "Find the steady-state concentration for the previous drug model.", marks: 1, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Definition of steady state.", workingLatex: "\\text{Steady state: } \\displaystyle\\frac{dC}{dt} = 0.", explanation: "At equilibrium the concentration is no longer changing — input and clearance rates balance perfectly." }, { stepNumber: 2, description: "Set the DE equal to zero.", workingLatex: "0 = -0.1\\,C^* + 5", explanation: "Use the model from the previous question and set the derivative to zero. \\(C^*\\) denotes the equilibrium concentration." }, { stepNumber: 3, description: "Solve for \\(C^*\\).", workingLatex: "0.1\\,C^* = 5 \\;\\Rightarrow\\; C^* = \\displaystyle\\frac{5}{0.1} = 50", explanation: "A direct linear solve. The units balance: \\(5\\) mg/hr in, eliminated at \\(0.1\\times 50 = 5\\) mg/hr — input matches output exactly." }, { stepNumber: 4, description: "Confirm with the limit of \\(C(t)\\).", workingLatex: "\\lim_{t \\to \\infty} 50\\left(1 - e^{-0.1t}\\right) = 50(1 - 0) = 50\\;\\checkmark", explanation: "The closed-form solution asymptotes to \\(50\\) mg as \\(t \\to \\infty\\), confirming the steady-state value." } ], finalAnswer: "\\(50\\) mg." } },
  // ── More models ────
  { id: "y2in10-031", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 31", difficulty: "Challenge", questionText: "An investment grows at rate 0.06 but has continuous withdrawals of 2000/yr: \\(\\displaystyle\\frac{dA}{dt} = 0.06A - 2000\\). Solve with \\(A(0) = 30000\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dA}{dt} = 0.06A - 2000", explanation: "Continuous compound growth at \\(6\\%\\) competes with a flat continuous withdrawal of \\(\\$2000\\)/yr. The equilibrium balance occurs where these match." }, { stepNumber: 2, description: "Identify the DE type and find the equilibrium.", workingLatex: "0 = 0.06A^* - 2000 \\;\\Rightarrow\\; A^* = \\displaystyle\\frac{2000}{0.06} = \\displaystyle\\frac{100000}{3} \\approx 33{,}333.33", explanation: "Linear first-order with constant coefficients. The equilibrium balance \\(A^* = 33{,}333.33\\) sets the natural reference: if \\(A < A^*\\), the account drains; if \\(A > A^*\\), it grows." }, { stepNumber: 3, description: "Substitute \\(u = A - A^*\\) to reduce to a pure exponential equation.", workingLatex: "\\displaystyle\\frac{du}{dt} = 0.06(A - A^*) = 0.06u", explanation: "Subtracting the equilibrium turns the inhomogeneous linear DE into the simplest growth equation. This is the cleanest way to solve linear ODEs by inspection." }, { stepNumber: 4, description: "Integrate the homogeneous equation.", workingLatex: "u(t) = u_0\\,e^{0.06t}", explanation: "Standard exponential growth solution. The constant \\(u_0\\) is fixed by the initial condition." }, { stepNumber: 5, description: "Apply the initial condition \\(A(0) = 30000\\).", workingLatex: "u_0 = A(0) - A^* = 30000 - 33333.33 = -3333.33", explanation: "Since the starting balance is below equilibrium, \\(u_0\\) is negative — the account is in deficit and will drain over time." }, { stepNumber: 6, description: "Recover \\(A(t)\\).", workingLatex: "A(t) = A^* + u(t) = 33333.33 - 3333.33\\,e^{0.06t}", explanation: "Reverse the substitution. The exponential term grows, so the second piece becomes increasingly negative — the account heads toward zero." }, { stepNumber: 7, description: "Verification.", workingLatex: "A(0) = 33333.33 - 3333.33 = 30000\\;\\checkmark \\quad\\text{and}\\quad \\displaystyle\\frac{dA}{dt} = -0.06\\cdot 3333.33\\,e^{0.06t} = 0.06A - 2000\\;\\checkmark", explanation: "Both the initial value and the DE are satisfied identically. The minus sign on the exponential means the account is being depleted by the withdrawals." } ], finalAnswer: "\\(A(t) \\approx 33{,}333.33 - 3333.33\\,e^{0.06t}\\)." } },
  { id: "y2in10-032", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 32", difficulty: "Standard", questionText: "Find the time the account empties.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the model.", workingLatex: "A(t) = 33333.33 - 3333.33\\,e^{0.06t}", explanation: "From the previous question. The account empties when \\(A(t) = 0\\) — we need to solve for that time." }, { stepNumber: 2, description: "Set \\(A(t) = 0\\).", workingLatex: "0 = 33333.33 - 3333.33\\,e^{0.06t}", explanation: "An exhausted account has balance zero. Rearrange to isolate the exponential factor." }, { stepNumber: 3, description: "Solve for the exponential.", workingLatex: "3333.33\\,e^{0.06t} = 33333.33 \\;\\Rightarrow\\; e^{0.06t} = 10", explanation: "Divide both sides by \\(3333.33\\). The ratio simplifies to \\(10\\) — exactly the ratio of equilibrium balance to deficit." }, { stepNumber: 4, description: "Take logs and solve for \\(t\\).", workingLatex: "0.06t = \\ln 10 \\;\\Rightarrow\\; t = \\displaystyle\\frac{\\ln 10}{0.06}", explanation: "Standard log step. Closed form in terms of \\(\\ln 10\\)." }, { stepNumber: 5, description: "Evaluate numerically.", workingLatex: "t = \\displaystyle\\frac{\\ln 10}{0.06} \\approx \\displaystyle\\frac{2.3026}{0.06} \\approx 38.38\\text{ years}", explanation: "About \\(38\\) years from now the account will be empty if the withdrawals and growth rate stay the same." }, { stepNumber: 6, description: "Sanity-check the trend.", workingLatex: "A(0) = 30000 > 0,\\;\\;A(38) \\approx 0,\\;\\;A(40) < 0.", explanation: "The closed form is monotonically decreasing in \\(t\\) once \\(A < A^*\\), so the root is unique. Past \\(t \\approx 38.4\\) yr the model would give negative balances — at which point the model breaks down (you can't withdraw from nothing)." } ], finalAnswer: "\\(t = \\displaystyle\\frac{\\ln 10}{0.06} \\approx 38.4\\) years." } },
  { id: "y2in10-033", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 33", difficulty: "Challenge", questionText: "Yeast grows logistically: \\(\\displaystyle\\frac{dY}{dt} = 0.3Y(1 - Y/500)\\), \\(Y(0) = 50\\). Find \\(Y(10)\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dY}{dt} = 0.3Y\\!\\left(1 - \\displaystyle\\frac{Y}{500}\\right)", explanation: "Standard logistic equation: intrinsic per-capita growth rate \\(r = 0.3\\), carrying capacity \\(M = 500\\). For small \\(Y\\) the growth is nearly exponential; near \\(Y = M\\) growth flattens out." }, { stepNumber: 2, description: "Identify the DE type and write the general solution.", workingLatex: "Y(t) = \\displaystyle\\frac{M}{1 + Ae^{-rt}} = \\displaystyle\\frac{500}{1 + Ae^{-0.3t}}", explanation: "The closed-form logistic solution. \\(A\\) is fixed by the initial condition: \\(A = (M - Y_0)/Y_0\\)." }, { stepNumber: 3, description: "Find \\(A\\) from \\(Y(0) = 50\\).", workingLatex: "A = \\displaystyle\\frac{500 - 50}{50} = \\displaystyle\\frac{450}{50} = 9", explanation: "The initial deviation from the carrying capacity, normalised by the starting population." }, { stepNumber: 4, description: "Write the specific solution.", workingLatex: "Y(t) = \\displaystyle\\frac{500}{1 + 9\\,e^{-0.3t}}", explanation: "Substitute \\(A = 9\\) into the general form. The solution is now fully specified." }, { stepNumber: 5, description: "Evaluate the exponent at \\(t = 10\\).", workingLatex: "-0.3 \\times 10 = -3 \\;\\Rightarrow\\; e^{-3} \\approx 0.049787", explanation: "Direct calculation of the exponential factor at the target time." }, { stepNumber: 6, description: "Plug in and simplify.", workingLatex: "Y(10) = \\displaystyle\\frac{500}{1 + 9 \\times 0.049787} = \\displaystyle\\frac{500}{1 + 0.44808} = \\displaystyle\\frac{500}{1.44808}", explanation: "Multiply, add, then divide. Keep extra decimal places through the computation to control rounding error." }, { stepNumber: 7, description: "Final numerical value.", workingLatex: "Y(10) \\approx 345.28 \\approx 345", explanation: "At \\(t = 10\\), the yeast population is about \\(345\\) — well on its way to the carrying capacity of \\(500\\) but not yet saturated." }, { stepNumber: 8, description: "Verification.", workingLatex: "Y(0) = \\displaystyle\\frac{500}{1 + 9} = 50\\;\\checkmark \\quad\\text{and}\\quad \\lim_{t \\to \\infty} Y = 500.", explanation: "Both the IC and the long-run carrying capacity are correct; the intermediate value \\(345\\) sits sensibly between them." } ], finalAnswer: "\\(Y(10) \\approx 345\\)." } },
  { id: "y2in10-034", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 34", difficulty: "Challenge", questionText: "Find terminal velocity when \\(\\displaystyle\\frac{dv}{dt} = g - kv^2\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dv}{dt} = g - kv^2", explanation: "Newton's second law with gravity (\\(+g\\)) and quadratic drag (\\(-kv^2\\)). At low speeds gravity dominates and the object accelerates; at high speeds drag catches up and the net force vanishes." }, { stepNumber: 2, description: "Definition of terminal velocity.", workingLatex: "\\text{Terminal: } \\displaystyle\\frac{dv}{dt} = 0.", explanation: "Terminal velocity is the steady state — the object stops accelerating because gravitational pull and drag exactly cancel." }, { stepNumber: 3, description: "Set the DE to zero and solve.", workingLatex: "0 = g - kv_{\\text{term}}^2 \\;\\Rightarrow\\; kv_{\\text{term}}^2 = g \\;\\Rightarrow\\; v_{\\text{term}}^2 = \\displaystyle\\frac{g}{k}", explanation: "A direct algebraic solve. The squared form falls out cleanly because the drag is quadratic." }, { stepNumber: 4, description: "Take the positive square root.", workingLatex: "v_{\\text{term}} = \\sqrt{\\displaystyle\\frac{g}{k}}", explanation: "We pick the positive root — terminal velocity in a downward fall is a positive speed (and the negative root would correspond to a non-physical 'upward terminal velocity')." }, { stepNumber: 5, description: "Sanity check.", workingLatex: "k \\uparrow \\;\\Rightarrow\\; v_{\\text{term}} \\downarrow \\quad\\text{and}\\quad g \\uparrow \\;\\Rightarrow\\; v_{\\text{term}} \\uparrow.", explanation: "Heavier drag means lower terminal velocity (a parachute slows you down). Stronger gravity raises it (you'd terminal faster on Jupiter). Both match physical intuition." } ], finalAnswer: "\\(v_{\\text{term}} = \\sqrt{\\displaystyle\\frac{g}{k}}\\)." } },
  { id: "y2in10-035", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 35", difficulty: "Challenge", questionText: "A tank with cross-sectional area 4 m² has water leaving through a hole at rate \\(0.2\\sqrt h\\) m³/s. Find \\(h(t)\\) given \\(h(0) = 9\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "A\\,\\displaystyle\\frac{dh}{dt} = -0.2\\sqrt h \\;\\Rightarrow\\; \\displaystyle\\frac{dh}{dt} = -\\displaystyle\\frac{0.2\\sqrt h}{4} = -0.05\\sqrt h", explanation: "Conservation of volume: \\(A\\,dh/dt\\) equals the (negative) outflow rate. This is essentially Torricelli's law — outflow proportional to \\(\\sqrt h\\) because the exit speed depends on hydrostatic pressure as \\(\\sqrt{2gh}\\)." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Separable nonlinear ODE in } h.", explanation: "Right-hand side factors as \\(g(t)\\,h(h_{\\text{var}}) = -0.05 \\cdot \\sqrt h\\) — standard separation of variables." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dh}{\\sqrt h} = -0.05\\,dt \\;\\Rightarrow\\; h^{-1/2}\\,dh = -0.05\\,dt", explanation: "Divide both sides by \\(\\sqrt h\\) (legitimate while \\(h > 0\\)). The \\(h\\) and \\(t\\) variables are now fully separated." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int h^{-1/2}\\,dh = \\displaystyle\\int -0.05\\,dt \\;\\Rightarrow\\; 2\\sqrt h = -0.05t + C", explanation: "Power rule: \\(\\displaystyle\\int h^{-1/2}\\,dh = h^{1/2}/(1/2) = 2\\sqrt h\\). The right side is just \\(-0.05t\\) plus a constant." }, { stepNumber: 5, description: "Apply the initial condition \\(h(0) = 9\\).", workingLatex: "2\\sqrt 9 = 0 + C \\;\\Rightarrow\\; C = 6", explanation: "Substitute \\(t = 0, h = 9\\); \\(\\sqrt 9 = 3\\), so \\(C = 2 \\cdot 3 = 6\\)." }, { stepNumber: 6, description: "Solve for \\(\\sqrt h\\), then for \\(h\\).", workingLatex: "2\\sqrt h = 6 - 0.05t \\;\\Rightarrow\\; \\sqrt h = 3 - 0.025t \\;\\Rightarrow\\; h(t) = \\left(3 - 0.025t\\right)^2", explanation: "Divide by \\(2\\), then square. Valid only for \\(t \\le 120\\) s; beyond that \\(\\sqrt h\\) would be negative (the tank has emptied)." }, { stepNumber: 7, description: "Identify the empty-time.", workingLatex: "h = 0 \\iff 3 - 0.025t = 0 \\iff t = 120\\text{ s}", explanation: "The tank drains entirely after \\(120\\) s, or \\(2\\) min. Past this point the model no longer applies (no water means no outflow)." }, { stepNumber: 8, description: "Verification.", workingLatex: "h(0) = 9\\;\\checkmark \\;\\;\\text{and}\\;\\;\\displaystyle\\frac{dh}{dt} = 2(3 - 0.025t)(-0.025) = -0.05(3 - 0.025t) = -0.05\\sqrt h\\;\\checkmark", explanation: "Differentiating recovers the DE exactly, and \\(h(0) = 9\\) matches the IC." } ], finalAnswer: "\\(h(t) = (3 - 0.025t)^2\\) for \\(0 \\le t \\le 120\\) s." } },
  { id: "y2in10-036", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 36", difficulty: "Standard", questionText: "A fund grows at rate \\(k\\) but is taxed at rate \\(m\\): \\(\\displaystyle\\frac{dP}{dt} = \\left(k - m\\right)P\\). Find its behaviour as \\(t \\to \\infty\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = (k - m)P", explanation: "Growth at proportional rate \\(k\\) reduced by proportional tax \\(m\\). The net per-capita rate is \\((k - m)\\) — the sign of this difference determines the qualitative behaviour." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Linear first-order, separable; pure exponential.}", explanation: "Standard exponential growth/decay equation with constant rate \\((k - m)\\). The solution structure depends entirely on this sign." }, { stepNumber: 3, description: "Integrate.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dP}{P} = \\displaystyle\\int (k - m)\\,dt \\;\\Rightarrow\\; \\ln|P| = (k - m)t + A", explanation: "Separate the variables and integrate. \\(\\ln|P|\\) is linear in \\(t\\)." }, { stepNumber: 4, description: "Exponentiate and apply IC \\(P(0) = P_0\\).", workingLatex: "P(t) = P_0\\,e^{(k - m)t}", explanation: "Exponentiating gives the standard form, with \\(P_0\\) the initial value absorbing the constant of integration." }, { stepNumber: 5, description: "Case analysis as \\(t \\to \\infty\\).", workingLatex: "\\begin{cases} k > m: & P(t) \\to \\infty \\;\\;\\text{(grows)} \\\\ k = m: & P(t) = P_0 \\;\\;\\text{(constant)} \\\\ k < m: & P(t) \\to 0 \\;\\;\\text{(decays)} \\end{cases}", explanation: "Three regimes determined by the sign of \\((k - m)\\). Tax less than growth → fund grows; tax exactly balances growth → fund holds steady; tax exceeds growth → fund eventually empties." }, { stepNumber: 6, description: "Verification.", workingLatex: "\\displaystyle\\frac{d}{dt}\\!\\left[P_0\\,e^{(k - m)t}\\right] = (k - m)P_0\\,e^{(k - m)t} = (k - m)P\\;\\checkmark", explanation: "Differentiating the closed form recovers the DE — the trichotomy is reliable." } ], finalAnswer: "\\(P(t) = P_0\\,e^{(k - m)t}\\); grows if \\(k > m\\), decays if \\(k < m\\), constant if \\(k = m\\)." } },
  { id: "y2in10-037", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 37", difficulty: "Challenge", questionText: "A lake of 10⁶ m³ has pollutant that decays at 1% per year and is naturally diluted by inflow-outflow giving an additional 2%: \\(\\displaystyle\\frac{dP}{dt} = -0.03P\\), \\(P(0) = 5000\\). Find time for pollutant to halve.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = -0.03P,\\quad P(0) = 5000", explanation: "Two loss processes combine into a single net first-order decay: \\(1\\%\\) from chemical breakdown and \\(2\\%\\) from dilution, giving an effective rate \\(0.03\\)/yr." }, { stepNumber: 2, description: "Identify the DE type and solve.", workingLatex: "P(t) = P_0\\,e^{-0.03t} = 5000\\,e^{-0.03t}", explanation: "Pure exponential decay — the solution is immediate from separation of variables (or by recognising the standard \\(dP/dt = -\\lambda P\\) template)." }, { stepNumber: 3, description: "Set up the half-life condition.", workingLatex: "P(t_{1/2}) = \\displaystyle\\frac{P_0}{2} \\;\\Rightarrow\\; e^{-0.03\\,t_{1/2}} = \\displaystyle\\frac{1}{2}", explanation: "We want the time at which the pollutant amount has fallen to half its initial. Divide through by \\(P_0\\) — the initial value drops out, so the half-life depends only on the rate." }, { stepNumber: 4, description: "Take logs.", workingLatex: "-0.03\\,t_{1/2} = -\\ln 2 \\;\\Rightarrow\\; t_{1/2} = \\displaystyle\\frac{\\ln 2}{0.03}", explanation: "Standard half-life formula \\(t_{1/2} = \\ln 2 / \\lambda\\)." }, { stepNumber: 5, description: "Evaluate numerically.", workingLatex: "t_{1/2} = \\displaystyle\\frac{0.69315}{0.03} \\approx 23.10\\text{ years}", explanation: "About \\(23\\) years for the lake to clear half its pollutant under these combined processes." }, { stepNumber: 6, description: "Verification.", workingLatex: "P(23.10) = 5000\\,e^{-0.03 \\times 23.10} = 5000\\,e^{-0.693} \\approx 5000 \\times 0.5 = 2500\\;\\checkmark", explanation: "Half of the initial \\(5000\\) is recovered, confirming the half-life." } ], finalAnswer: "\\(t_{1/2} = \\displaystyle\\frac{\\ln 2}{0.03} \\approx 23.1\\) years." } },
  { id: "y2in10-038", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 38", difficulty: "Challenge", questionText: "A body cools: \\(T = 20 + 17 e^{-0.1t}\\) from a normal 37°C. When was death?", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "T(t) = 20 + 17\\,e^{-0.1t}", explanation: "Newton-cooling form: ambient \\(T_\\infty = 20^\\circ\\)C, with an initial excess \\(T_0 - T_\\infty = 17^\\circ\\)C that decays exponentially with rate constant \\(0.1\\)/hr." }, { stepNumber: 2, description: "Find the temperature at \\(t = 0\\).", workingLatex: "T(0) = 20 + 17\\,e^{0} = 20 + 17 = 37^\\circ\\text{C}", explanation: "The model starts the body at exactly normal living body temperature \\(37^\\circ\\)C. In a forensic cooling model, \\(t = 0\\) is by convention the moment of death." }, { stepNumber: 3, description: "Set up the death-time equation.", workingLatex: "T_{\\text{death}} = 37 \\;\\Leftrightarrow\\; 20 + 17\\,e^{-0.1t} = 37", explanation: "Death corresponds to the body still being at \\(37^\\circ\\)C — the moment before cooling has begun." }, { stepNumber: 4, description: "Solve for \\(t\\).", workingLatex: "17\\,e^{-0.1t} = 17 \\;\\Rightarrow\\; e^{-0.1t} = 1 \\;\\Rightarrow\\; t = 0", explanation: "The only solution is \\(t = 0\\). The exponential factor equals \\(1\\) precisely when the exponent is zero." }, { stepNumber: 5, description: "Interpret physically.", workingLatex: "t = 0 \\text{ marks the start of the cooling process.}", explanation: "In context, the model's clock starts at the instant of death. Any observation that yields the cooling curve above implies the death happened at the time corresponding to \\(t = 0\\) — i.e., 'now' minus however many hours the measurement was made after death." }, { stepNumber: 6, description: "Reframe with a sample data point.", workingLatex: "\\text{E.g., if } T = 30^\\circ\\text{C now: } 20 + 17\\,e^{-0.1t} = 30 \\Rightarrow t = \\displaystyle\\frac{\\ln(17/10)}{0.1} \\approx 5.31\\text{ hr ago.}", explanation: "If a later body temperature is given, that fixes the time since death. Without that datum, the answer is simply that the cooling model places death at its origin \\(t = 0\\)." }, { stepNumber: 7, description: "Verification.", workingLatex: "T(0) = 20 + 17 = 37^\\circ\\text{C}\\;\\checkmark", explanation: "The temperature at \\(t = 0\\) matches the normal living temperature exactly — consistent with the death-as-start-of-cooling convention." } ], finalAnswer: "\\(t = 0\\) — death corresponds to the start of the cooling model, when \\(T = 37^\\circ\\)C." } },
  { id: "y2in10-039", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 39", difficulty: "Standard", questionText: "A capacitor discharges: \\(\\displaystyle\\frac{dQ}{dt} = -\\displaystyle\\frac{Q}{RC}\\), \\(Q(0) = Q_0\\). Find \\(Q(t)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dQ}{dt} = -\\displaystyle\\frac{Q}{RC}", explanation: "Discharge through a resistor: current \\(I = Q/RC\\) flows out (negative for \\(Q\\)), so \\(dQ/dt = -Q/RC\\). The product \\(RC\\) is the time constant \\(\\tau\\)." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Linear first-order; separable (pure exponential decay).}", explanation: "Same template as radioactive decay or Newton cooling about ambient zero." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dQ}{Q} = -\\displaystyle\\frac{1}{RC}\\,dt", explanation: "Divide both sides by \\(Q\\). All \\(Q\\) on the left, all \\(t\\) on the right." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dQ}{Q} = \\displaystyle\\int -\\displaystyle\\frac{1}{RC}\\,dt \\;\\Rightarrow\\; \\ln|Q| = -\\displaystyle\\frac{t}{RC} + A", explanation: "Standard log integral on the left; constant integration on the right." }, { stepNumber: 5, description: "Exponentiate and absorb the constant.", workingLatex: "Q(t) = B\\,e^{-t/(RC)}\\quad\\text{where } B = e^A.", explanation: "Exponentiate both sides. The arbitrary constant \\(A\\) becomes a multiplicative constant \\(B = e^A > 0\\) (the sign of \\(Q\\) is taken positive here)." }, { stepNumber: 6, description: "Apply the initial condition \\(Q(0) = Q_0\\).", workingLatex: "Q_0 = B\\,e^0 = B \\;\\Rightarrow\\; B = Q_0", explanation: "Plugging in \\(t = 0\\) pins the constant to the initial charge." }, { stepNumber: 7, description: "State the solution.", workingLatex: "Q(t) = Q_0\\,e^{-t/(RC)}", explanation: "Classic RC discharge formula. The charge decays exponentially with time constant \\(\\tau = RC\\)." }, { stepNumber: 8, description: "Verification.", workingLatex: "\\displaystyle\\frac{dQ}{dt} = -\\displaystyle\\frac{Q_0}{RC}\\,e^{-t/(RC)} = -\\displaystyle\\frac{Q}{RC}\\;\\checkmark", explanation: "Differentiating the closed form recovers the DE exactly." } ], finalAnswer: "\\(Q(t) = Q_0\\,e^{-t/(RC)}\\)." } },
  { id: "y2in10-040", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 40", difficulty: "Foundation", questionText: "For \\(Q = Q_0 e^{-t/\\tau}\\) with \\(\\tau = RC\\), find the time for charge to drop to 1/e of its initial.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the condition.", workingLatex: "Q(t) = \\displaystyle\\frac{Q_0}{e} \\;\\Leftrightarrow\\; Q_0\\,e^{-t/\\tau} = \\displaystyle\\frac{Q_0}{e}", explanation: "We want the time at which the charge has fallen to \\(1/e \\approx 0.368\\) of its starting value — the natural 'time-constant' definition." }, { stepNumber: 2, description: "Cancel \\(Q_0\\) and simplify.", workingLatex: "e^{-t/\\tau} = \\displaystyle\\frac{1}{e} = e^{-1}", explanation: "Divide both sides by \\(Q_0\\). The starting value drops out — time-constants don't depend on starting amplitude." }, { stepNumber: 3, description: "Equate exponents.", workingLatex: "-\\displaystyle\\frac{t}{\\tau} = -1 \\;\\Rightarrow\\; t = \\tau", explanation: "Same base on both sides, so the exponents match. The result is the defining property of \\(\\tau\\): after one time-constant, the signal has decayed to \\(1/e\\)." }, { stepNumber: 4, description: "Interpret the result.", workingLatex: "t = \\tau = RC", explanation: "The 'characteristic time' for an RC discharge is exactly \\(RC\\). After \\(\\tau\\) the charge is at \\(\\approx 37\\%\\) of initial; after \\(5\\tau\\) it's effectively zero." } ], finalAnswer: "\\(t = \\tau\\)." } },
  // ── Exam prep ────
  { id: "y2in10-041", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 41", difficulty: "Challenge", questionText: "Set up and solve: the rate of spread of a rumour is proportional to both those who know (N) and those who don't (total 500 minus N). Initially 10 know. After 2 days, 50 know. Find \\(N(5)\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the DE.", workingLatex: "\\displaystyle\\frac{dN}{dt} = k\\,N\\,(500 - N)", explanation: "The wording 'proportional to both those who know and those who don't' is the verbal recipe for a logistic equation with carrying capacity \\(M = 500\\)." }, { stepNumber: 2, description: "Identify the DE type and write the general solution.", workingLatex: "N(t) = \\displaystyle\\frac{500}{1 + A\\,e^{-rt}},\\quad r = 500k", explanation: "Standard logistic closed form. The intrinsic growth rate \\(r\\) is the carrying-capacity \\(\\times\\) the proportionality constant: \\(r = kM = 500k\\)." }, { stepNumber: 3, description: "Use \\(N(0) = 10\\) to find \\(A\\).", workingLatex: "10 = \\displaystyle\\frac{500}{1 + A} \\;\\Rightarrow\\; 1 + A = 50 \\;\\Rightarrow\\; A = 49", explanation: "Plug \\(t = 0, N = 10\\). Solving gives \\(A = 49\\), and the specific solution is \\(N(t) = 500/(1 + 49 e^{-rt})\\)." }, { stepNumber: 4, description: "Use \\(N(2) = 50\\) to find \\(r\\).", workingLatex: "50 = \\displaystyle\\frac{500}{1 + 49\\,e^{-2r}} \\;\\Rightarrow\\; 1 + 49\\,e^{-2r} = 10 \\;\\Rightarrow\\; 49\\,e^{-2r} = 9 \\;\\Rightarrow\\; e^{-2r} = \\displaystyle\\frac{9}{49}", explanation: "A second data point pins down the spread rate. Isolate the exponential factor; this gives a clean ratio of \\(9/49\\) — convenient for the next step." }, { stepNumber: 5, description: "Solve for \\(r\\) (and equivalently \\(k\\)).", workingLatex: "-2r = \\ln\\!\\left(\\displaystyle\\frac{9}{49}\\right) \\;\\Rightarrow\\; r = \\displaystyle\\frac{1}{2}\\ln\\!\\left(\\displaystyle\\frac{49}{9}\\right) \\approx \\displaystyle\\frac{1}{2}\\,(1.6946) \\approx 0.8473", explanation: "Take logs and flip the sign by writing \\(\\ln(9/49) = -\\ln(49/9)\\). Numerically \\(r \\approx 0.847\\)/day." }, { stepNumber: 6, description: "Evaluate the exponent at \\(t = 5\\).", workingLatex: "e^{-5r} = \\left(e^{-2r}\\right)^{5/2} = \\left(\\displaystyle\\frac{9}{49}\\right)^{5/2}", explanation: "We can avoid computing \\(r\\) explicitly: \\(e^{-5r}\\) is just the \\(5/2\\) power of the known quantity \\(e^{-2r} = 9/49\\)." }, { stepNumber: 7, description: "Compute the numerical value.", workingLatex: "\\left(\\displaystyle\\frac{9}{49}\\right)^{5/2} = \\left(\\displaystyle\\frac{9}{49}\\right)^{2} \\sqrt{\\displaystyle\\frac{9}{49}} = \\displaystyle\\frac{81}{2401} \\cdot \\displaystyle\\frac{3}{7} = \\displaystyle\\frac{243}{16807} \\approx 0.01446", explanation: "Decompose \\(5/2 = 2 + 1/2\\) and use \\(\\sqrt{9/49} = 3/7\\). The arithmetic stays exact and the numerical value is straightforward." }, { stepNumber: 8, description: "Substitute into \\(N(5)\\).", workingLatex: "N(5) = \\displaystyle\\frac{500}{1 + 49 \\times 0.01446} = \\displaystyle\\frac{500}{1 + 0.7085} = \\displaystyle\\frac{500}{1.7085}", explanation: "Plug back into the logistic formula. The denominator is well below \\(2\\), so we're already past the halfway mark in the spread." }, { stepNumber: 9, description: "Final numerical answer.", workingLatex: "N(5) \\approx 292.65 \\approx 293\\text{ people}", explanation: "After \\(5\\) days, about \\(293\\) of the \\(500\\) people have heard the rumour — the spread has accelerated past its midpoint." }, { stepNumber: 10, description: "Verification of the curve at the two data points.", workingLatex: "N(0) = \\displaystyle\\frac{500}{50} = 10\\;\\checkmark,\\quad N(2) = \\displaystyle\\frac{500}{1 + 49 \\cdot \\displaystyle\\frac{9}{49}} = \\displaystyle\\frac{500}{10} = 50\\;\\checkmark", explanation: "Both observations are reproduced exactly by the fitted logistic curve, so the projection \\(N(5) \\approx 293\\) is reliable within the model." } ], finalAnswer: "\\(N(5) \\approx 293\\) people." } },
  { id: "y2in10-042", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 42", difficulty: "Standard", questionText: "A 100 g sugar cube dissolves so that \\(\\displaystyle\\frac{dm}{dt} = -0.01m\\). Solve for \\(m(t)\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dm}{dt} = -0.01\\,m,\\quad m(0) = 100", explanation: "The dissolution rate is proportional to the remaining mass — a standard first-order decay. Bigger cube, faster mass loss; smaller cube, slower." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Linear first-order, separable; pure exponential decay.}", explanation: "Template \\(dm/dt = -\\lambda m\\) with \\(\\lambda = 0.01\\). The solution is the standard decaying exponential." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dm}{m} = -0.01\\,dt", explanation: "All mass terms on the left, time on the right. Valid while \\(m > 0\\)." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dm}{m} = \\displaystyle\\int -0.01\\,dt \\;\\Rightarrow\\; \\ln|m| = -0.01\\,t + A", explanation: "Standard log integral. The constant \\(A\\) carries the initial value." }, { stepNumber: 5, description: "Exponentiate.", workingLatex: "m(t) = B\\,e^{-0.01t},\\quad B = e^A > 0.", explanation: "Take exponentials of both sides; the log disappears and we get the multiplicative-constant form." }, { stepNumber: 6, description: "Apply the IC \\(m(0) = 100\\).", workingLatex: "100 = B\\,e^0 = B \\;\\Rightarrow\\; B = 100", explanation: "The starting mass pins down the multiplicative constant." }, { stepNumber: 7, description: "Final closed form.", workingLatex: "m(t) = 100\\,e^{-0.01t}", explanation: "Standard exponential decay with rate constant \\(0.01\\). The mass halves every \\(t_{1/2} = \\ln 2 / 0.01 \\approx 69.3\\) min." }, { stepNumber: 8, description: "Verification.", workingLatex: "m(0) = 100\\;\\checkmark \\quad\\text{and}\\quad \\displaystyle\\frac{dm}{dt} = -0.01\\cdot 100\\,e^{-0.01t} = -0.01\\,m\\;\\checkmark", explanation: "Both the IC and the DE are satisfied identically — the solution is correct." } ], finalAnswer: "\\(m(t) = 100\\,e^{-0.01t}\\) g." } },
  { id: "y2in10-043", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 43", difficulty: "Standard", questionText: "A surface temperature satisfies \\(T - T_{\\infty} = \\left(T_0 - T_{\\infty}\\right)e^{-kt}\\). Use this to explain why \\(T\\) approaches \\(T_{\\infty}\\) asymptotically.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the model structure.", workingLatex: "T(t) - T_\\infty = (T_0 - T_\\infty)\\,e^{-kt}", explanation: "Newton's law of cooling: the deviation from the ambient temperature decays exponentially. \\(T_\\infty\\) is the surrounding temperature, \\(T_0\\) is the initial body temperature." }, { stepNumber: 2, description: "Re-state explicitly.", workingLatex: "T(t) = T_\\infty + (T_0 - T_\\infty)\\,e^{-kt}", explanation: "Add \\(T_\\infty\\) to both sides. The body temperature is the ambient plus a decaying excess (or deficit) term." }, { stepNumber: 3, description: "Take the limit as \\(t \\to \\infty\\).", workingLatex: "\\lim_{t\\to\\infty} e^{-kt} = 0 \\quad (\\text{since } k > 0)", explanation: "An exponential with negative exponent vanishes in the limit — this is the entire mechanism behind the asymptotic approach." }, { stepNumber: 4, description: "Multiply through and combine.", workingLatex: "\\lim_{t\\to\\infty} (T_0 - T_\\infty)\\,e^{-kt} = (T_0 - T_\\infty)\\cdot 0 = 0", explanation: "Whatever finite difference \\(T_0 - T_\\infty\\) we start with, it's multiplied by something tending to zero." }, { stepNumber: 5, description: "Conclude the asymptote.", workingLatex: "\\lim_{t\\to\\infty} T(t) = T_\\infty + 0 = T_\\infty", explanation: "The body temperature approaches the ambient temperature — but never quite reaches it (\\(e^{-kt} > 0\\) for all finite \\(t\\))." }, { stepNumber: 6, description: "Physical interpretation.", workingLatex: "T(t) \\to T_\\infty\\;\\;\\text{but } T(t) \\neq T_\\infty \\text{ for any finite } t.", explanation: "The model never lets \\(T\\) reach ambient exactly — it asymptotes. Physically this is because the cooling rate \\(\\propto (T - T_\\infty)\\) shrinks to zero as the difference shrinks, so progress slows perpetually." } ], finalAnswer: "As \\(t \\to \\infty\\), \\(e^{-kt} \\to 0\\), so \\(T \\to T_\\infty\\) asymptotically — never reaching it exactly in finite time." } },
  { id: "y2in10-044", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 44", difficulty: "Standard", questionText: "Rain fills a tank at constant rate 5 m³/h. The tank leaks at rate proportional to height (1.0 /h). Set up a DE for \\(h\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the model components.", workingLatex: "\\text{Rate in } = 5,\\quad \\text{rate out } = 1.0\\,h", explanation: "Rain adds water at constant rate; leak is proportional to head with constant \\(1.0\\)/h. For a tank with unit cross-section, \\(dh/dt\\) equals (rate in) − (rate out)." }, { stepNumber: 2, description: "Assemble the DE.", workingLatex: "\\displaystyle\\frac{dh}{dt} = 5 - h", explanation: "Net rate of change of height equals net inflow per unit area. Assuming unit cross-sectional area, the model is \\(dh/dt = 5 - h\\)." }, { stepNumber: 3, description: "Identify the DE type and find equilibrium.", workingLatex: "0 = 5 - h^* \\;\\Rightarrow\\; h^* = 5", explanation: "Linear first-order. The equilibrium height is where inflow and outflow balance — \\(h^* = 5\\) m." }, { stepNumber: 4, description: "Substitute \\(u = h - 5\\) and solve.", workingLatex: "\\displaystyle\\frac{du}{dt} = -u \\;\\Rightarrow\\; u = u_0\\,e^{-t}", explanation: "Shifting by the equilibrium turns the linear inhomogeneous equation into a pure decay equation." }, { stepNumber: 5, description: "Apply \\(h(0) = 0\\) (empty tank).", workingLatex: "u_0 = h(0) - 5 = -5 \\;\\Rightarrow\\; u(t) = -5\\,e^{-t}", explanation: "Starting empty, the deviation from equilibrium is \\(-5\\), so the closed-form deviation is \\(-5e^{-t}\\)." }, { stepNumber: 6, description: "Recover \\(h(t)\\).", workingLatex: "h(t) = 5 + u(t) = 5 - 5\\,e^{-t} = 5\\left(1 - e^{-t}\\right)", explanation: "Add back the equilibrium. The height rises monotonically from \\(0\\) toward \\(5\\) m — the standard 'approach to equilibrium' shape." }, { stepNumber: 7, description: "Verification.", workingLatex: "\\displaystyle\\frac{dh}{dt} = 5\\,e^{-t} = 5 - 5(1 - e^{-t}) = 5 - h\\;\\checkmark", explanation: "Differentiating recovers the DE; \\(h(0) = 0\\) matches the initial condition." } ], finalAnswer: "\\(\\displaystyle\\frac{dh}{dt} = 5 - h\\); solution \\(h(t) = 5\\left(1 - e^{-t}\\right)\\)." } },
  { id: "y2in10-045", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 45", difficulty: "Foundation", questionText: "From the previous model, find the equilibrium height.", marks: 1, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Recall the DE.", workingLatex: "\\displaystyle\\frac{dh}{dt} = 5 - h", explanation: "The model from the previous question. Equilibrium occurs where the height stops changing." }, { stepNumber: 2, description: "Set \\(dh/dt = 0\\).", workingLatex: "0 = 5 - h^*", explanation: "By definition, equilibrium means the rate of change is zero — the inflow exactly matches the outflow." }, { stepNumber: 3, description: "Solve for \\(h^*\\).", workingLatex: "h^* = 5", explanation: "A direct linear solve. Inflow \\(5\\) balances outflow \\(1.0 \\times 5 = 5\\), confirming the steady state." }, { stepNumber: 4, description: "Confirm with the long-run limit.", workingLatex: "\\lim_{t\\to\\infty} 5\\left(1 - e^{-t}\\right) = 5 \\;\\checkmark", explanation: "The closed-form solution asymptotes to \\(5\\) m as \\(t \\to \\infty\\)." } ], finalAnswer: "\\(5\\) m." } },
  { id: "y2in10-046", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 46", difficulty: "Challenge", questionText: "Solve \\(\\displaystyle\\frac{dy}{dt} = t(10 - y)\\), \\(y(0) = 0\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["separable"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dy}{dt} = t\\,(10 - y),\\quad y(0) = 0", explanation: "An equilibrium at \\(y = 10\\): when \\(y < 10\\) the RHS is positive and \\(y\\) increases; when \\(y > 10\\) it decreases. The time-dependent factor \\(t\\) means the approach is faster as time passes." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Separable: RHS factors as } g(t)\\,h(y) = t \\cdot (10 - y).", explanation: "Both factors are present in clean form — standard separation of variables applies." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dy}{10 - y} = t\\,dt", explanation: "Divide both sides by \\((10 - y)\\) (valid while \\(y \\neq 10\\)) and multiply by \\(dt\\)." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dy}{10 - y} = \\displaystyle\\int t\\,dt \\;\\Rightarrow\\; -\\ln|10 - y| = \\displaystyle\\frac{t^2}{2} + C", explanation: "Reverse-chain log on the left with \\(f(y) = 10 - y, f'(y) = -1\\); standard power rule on the right." }, { stepNumber: 5, description: "Apply the IC \\(y(0) = 0\\).", workingLatex: "-\\ln|10 - 0| = 0 + C \\;\\Rightarrow\\; C = -\\ln 10", explanation: "Plug \\(t = 0, y = 0\\). The negative log of \\(10\\) gives the constant of integration." }, { stepNumber: 6, description: "Substitute back and combine logs.", workingLatex: "-\\ln|10 - y| = \\displaystyle\\frac{t^2}{2} - \\ln 10 \\;\\Rightarrow\\; \\ln\\!\\left(\\displaystyle\\frac{10}{10 - y}\\right) = \\displaystyle\\frac{t^2}{2}", explanation: "Move \\(-\\ln 10\\) across and combine the two logs into a single ratio. The argument is positive while \\(y < 10\\) (which is the case for our IC)." }, { stepNumber: 7, description: "Exponentiate and solve for \\(y\\).", workingLatex: "\\displaystyle\\frac{10}{10 - y} = e^{t^2/2} \\;\\Rightarrow\\; 10 - y = 10\\,e^{-t^2/2} \\;\\Rightarrow\\; y(t) = 10\\left(1 - e^{-t^2/2}\\right)", explanation: "Take reciprocals, then solve for \\(y\\). The closed form approaches the equilibrium \\(y = 10\\) Gaussian-fast (much faster than the standard exponential)." }, { stepNumber: 8, description: "Verification.", workingLatex: "y(0) = 10(1 - 1) = 0\\;\\checkmark \\;\\;\\text{and}\\;\\; \\displaystyle\\frac{dy}{dt} = 10\\cdot t\\,e^{-t^2/2} = t\\,(10 - y)\\;\\checkmark", explanation: "Both the IC and the DE check out identically — the closed form is correct." } ], finalAnswer: "\\(y = 10\\left(1 - e^{-t^2/2}\\right)\\)." } },
  { id: "y2in10-047", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 47", difficulty: "Standard", questionText: "A population was 500 at \\(t = 0\\) and 800 at \\(t = 4\\). Assume \\(\\displaystyle\\frac{dP}{dt} = kP\\). Find \\(k\\) and \\(P(10)\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the DE type and write the general solution.", workingLatex: "\\displaystyle\\frac{dP}{dt} = kP \\;\\Rightarrow\\; P(t) = P_0\\,e^{kt}", explanation: "Pure exponential growth. With two data points we can pin down both the initial value \\(P_0\\) and the rate \\(k\\)." }, { stepNumber: 2, description: "Apply \\(P(0) = 500\\).", workingLatex: "P_0 = 500 \\;\\Rightarrow\\; P(t) = 500\\,e^{kt}", explanation: "The first data point fixes \\(P_0\\) directly — at \\(t = 0\\), \\(P(t) = P_0\\)." }, { stepNumber: 3, description: "Use \\(P(4) = 800\\) to find \\(k\\).", workingLatex: "800 = 500\\,e^{4k} \\;\\Rightarrow\\; e^{4k} = 1.6 \\;\\Rightarrow\\; 4k = \\ln 1.6 \\;\\Rightarrow\\; k = \\displaystyle\\frac{\\ln 1.6}{4}", explanation: "The second data point gives an equation in \\(k\\). Divide, take logs, then solve." }, { stepNumber: 4, description: "Evaluate \\(k\\) numerically.", workingLatex: "k \\approx \\displaystyle\\frac{0.4700}{4} \\approx 0.1175\\text{ /time unit}", explanation: "About \\(11.75\\%\\) per time unit — a modest but compounding rate." }, { stepNumber: 5, description: "Compute \\(P(10)\\).", workingLatex: "P(10) = 500\\,e^{10k} = 500\\,e^{10\\,\\ln 1.6/4} = 500\\cdot 1.6^{10/4} = 500\\cdot 1.6^{2.5}", explanation: "Use the index law \\(e^{a\\ln b} = b^a\\) to express the answer cleanly as a power of \\(1.6\\)." }, { stepNumber: 6, description: "Evaluate \\(1.6^{2.5}\\).", workingLatex: "1.6^{2.5} = 1.6^2 \\cdot \\sqrt{1.6} = 2.56 \\cdot 1.2649 \\approx 3.2381", explanation: "Split into integer and fractional powers; this avoids large-power computations." }, { stepNumber: 7, description: "Final numerical answer.", workingLatex: "P(10) \\approx 500 \\times 3.2381 \\approx 1619", explanation: "The population reaches approximately \\(1619\\) at \\(t = 10\\) — roughly tripling from the start in \\(10\\) time units." }, { stepNumber: 8, description: "Verification.", workingLatex: "P(0) = 500\\;\\checkmark,\\quad P(4) = 500\\cdot 1.6^{1} = 800\\;\\checkmark", explanation: "Both given data points are reproduced exactly by the fitted curve." } ], finalAnswer: "\\(k = \\displaystyle\\frac{\\ln 1.6}{4} \\approx 0.1175\\);  \\(P(10) = 500\\cdot 1.6^{2.5} \\approx 1619\\)." } },
  { id: "y2in10-048", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 48", difficulty: "Challenge", questionText: "\\(\\displaystyle\\frac{dx}{dt} = c - \\alpha x\\) (pollutant in/out). Solve with \\(x(0) = 0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dx}{dt} = c - \\alpha x", explanation: "Constant pollutant input rate \\(c\\) competes with first-order removal at proportional rate \\(\\alpha\\). The equilibrium is \\(x^* = c/\\alpha\\), where input balances output." }, { stepNumber: 2, description: "Identify the DE type and find the equilibrium.", workingLatex: "\\text{Linear first-order; equilibrium } x^* = \\displaystyle\\frac{c}{\\alpha}.", explanation: "Set \\(dx/dt = 0\\): \\(c = \\alpha x^*\\) gives the steady-state concentration. The substitution \\(u = x - x^*\\) will reduce the DE to a pure decay equation." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "\\displaystyle\\frac{dx}{c - \\alpha x} = dt", explanation: "Standard rearrangement. All \\(x\\) on the left, time on the right." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dx}{c - \\alpha x} = \\displaystyle\\int dt \\;\\Rightarrow\\; -\\displaystyle\\frac{1}{\\alpha}\\ln|c - \\alpha x| = t + A", explanation: "Reverse chain rule with \\(f(x) = c - \\alpha x\\), \\(f'(x) = -\\alpha\\). The factor \\(-1/\\alpha\\) accounts for this." }, { stepNumber: 5, description: "Apply the IC \\(x(0) = 0\\).", workingLatex: "-\\displaystyle\\frac{1}{\\alpha}\\ln|c| = 0 + A \\;\\Rightarrow\\; A = -\\displaystyle\\frac{\\ln c}{\\alpha}", explanation: "Plug in \\(t = 0, x = 0\\). Assuming \\(c > 0\\), we drop the modulus and use \\(\\ln c\\) directly." }, { stepNumber: 6, description: "Rearrange to isolate the log.", workingLatex: "-\\displaystyle\\frac{1}{\\alpha}\\ln|c - \\alpha x| = t - \\displaystyle\\frac{\\ln c}{\\alpha} \\;\\Rightarrow\\; \\ln\\!\\left(\\displaystyle\\frac{c}{c - \\alpha x}\\right) = \\alpha t", explanation: "Multiply through by \\(-\\alpha\\) and combine the logs into a single ratio. The argument is positive while \\(x < c/\\alpha\\) (which is the regime starting from \\(x = 0\\))." }, { stepNumber: 7, description: "Exponentiate and solve for \\(x\\).", workingLatex: "\\displaystyle\\frac{c}{c - \\alpha x} = e^{\\alpha t} \\;\\Rightarrow\\; c - \\alpha x = c\\,e^{-\\alpha t} \\;\\Rightarrow\\; x(t) = \\displaystyle\\frac{c}{\\alpha}\\left(1 - e^{-\\alpha t}\\right)", explanation: "Take reciprocals, then solve. The result is the standard 'rise to equilibrium' form, climbing from \\(0\\) toward \\(c/\\alpha\\) with time constant \\(1/\\alpha\\)." }, { stepNumber: 8, description: "Verification.", workingLatex: "x(0) = 0\\;\\checkmark \\;\\;\\text{and}\\;\\; \\displaystyle\\frac{dx}{dt} = c\\,e^{-\\alpha t} = c - \\alpha\\cdot\\displaystyle\\frac{c}{\\alpha}(1 - e^{-\\alpha t}) = c - \\alpha x\\;\\checkmark", explanation: "Both the IC and the DE are satisfied exactly. As \\(t \\to \\infty\\), \\(x \\to c/\\alpha\\) — the predicted steady state." } ], finalAnswer: "\\(x(t) = \\displaystyle\\frac{c}{\\alpha}\\left(1 - e^{-\\alpha t}\\right)\\)." } },
  { id: "y2in10-049", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 49", difficulty: "Challenge", questionText: "At early stage, \\(I \\ll N\\). Approximate \\(\\displaystyle\\frac{dI}{dt} \\approx \\left(\\beta N - \\gamma\\right)I\\) and solve.", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model physically.", workingLatex: "\\displaystyle\\frac{dI}{dt} \\approx \\left(\\beta N - \\gamma\\right)I", explanation: "This is the early-stage SIR linearisation. \\(\\beta N\\) is the new-infection rate per infected (when \\(S \\approx N\\)) and \\(\\gamma\\) is the recovery rate; their difference \\(\\beta N - \\gamma\\) is the effective per-capita growth rate of \\(I\\)." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\displaystyle\\frac{dI}{dt} = rI \\;\\text{ with } r = \\beta N - \\gamma", explanation: "A linear, separable, first-order ODE with constant coefficient — the classic exponential-growth template." }, { stepNumber: 3, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dI}{I} = \\left(\\beta N - \\gamma\\right)dt", explanation: "Divide by \\(I\\) (valid since \\(I > 0\\) early in the outbreak) and multiply by \\(dt\\); each side now contains only one variable." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dI}{I} = \\displaystyle\\int \\left(\\beta N - \\gamma\\right)dt \\;\\Rightarrow\\; \\ln I = \\left(\\beta N - \\gamma\\right)t + C", explanation: "Standard antiderivatives — \\(\\ln I\\) on the left, a linear function of \\(t\\) on the right." }, { stepNumber: 5, description: "Exponentiate and apply IC \\(I(0) = I_0\\).", workingLatex: "I = e^{C} e^{(\\beta N - \\gamma)t} \\;\\Rightarrow\\; I_0 = e^{C} \\;\\Rightarrow\\; e^{C} = I_0", explanation: "Setting \\(t = 0\\) collapses the exponential factor to \\(1\\), pinning the multiplicative constant to the initial count." }, { stepNumber: 6, description: "State the explicit solution.", workingLatex: "I(t) = I_0\\,e^{(\\beta N - \\gamma)t}", explanation: "Exponential growth if \\(\\beta N > \\gamma\\) (outbreak); exponential decay if \\(\\beta N < \\gamma\\) (contained). The threshold \\(\\beta N = \\gamma\\) is the basic reproduction-number boundary \\(R_0 = 1\\)." }, { stepNumber: 7, description: "Verify by direct substitution.", workingLatex: "\\displaystyle\\frac{d}{dt}\\!\\left[I_0 e^{(\\beta N - \\gamma)t}\\right] = \\left(\\beta N - \\gamma\\right) I_0 e^{(\\beta N - \\gamma)t} = \\left(\\beta N - \\gamma\\right) I \\;\\checkmark", explanation: "Differentiating the proposed solution returns exactly the right-hand side of the DE, and \\(I(0) = I_0\\) is satisfied." } ], finalAnswer: "\\(I = I_0 e^{(\\beta N - \\gamma)t}\\)." } },
  { id: "y2in10-050", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 50", difficulty: "Foundation", questionText: "If a drug has half-life 24 hours, find how much of a 100 mg dose remains after 72 hours.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the half-life.", workingLatex: "\\text{Half-life } = 24\\text{ h} \\;\\Rightarrow\\; \\text{every } 24\\text{ h, amount halves}", explanation: "Pharmacokinetic first-order decay: the surviving fraction multiplies by \\(\\displaystyle\\frac{1}{2}\\) over each fixed half-life window, independent of starting amount." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\displaystyle\\frac{dM}{dt} = -kM \\;\\Rightarrow\\; M(t) = M_0\\left(\\displaystyle\\frac{1}{2}\\right)^{t/T_{1/2}}", explanation: "Exponential decay. Expressing the solution with base \\(\\displaystyle\\frac{1}{2}\\) and exponent \\(t/T_{1/2}\\) sidesteps the need to find \\(k\\) explicitly — the answer drops out from counting half-lives." }, { stepNumber: 3, description: "Count the number of half-lives.", workingLatex: "n = \\displaystyle\\frac{72}{24} = 3", explanation: "Three full half-life intervals fit into \\(72\\) hours." }, { stepNumber: 4, description: "Apply the formula.", workingLatex: "M(72) = 100\\cdot\\left(\\displaystyle\\frac{1}{2}\\right)^{3} = 100\\cdot\\displaystyle\\frac{1}{8}", explanation: "Each interval halves the remaining mass: \\(100 \\to 50 \\to 25 \\to 12.5\\), reproducing the same answer." }, { stepNumber: 5, description: "Evaluate and state the answer.", workingLatex: "M(72) = 12.5\\text{ mg}", explanation: "Twelve and a half milligrams remain — about an eighth of the dose." } ], finalAnswer: "12.5 mg." } },
  { id: "y2in10-051", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 51", difficulty: "Challenge", questionText: "A spherical snowball melts so that its volume decreases at rate proportional to its surface area: \\(\\displaystyle\\frac{dV}{dt} = -kV^{\\frac{2}{3}}\\). Solve.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model physically.", workingLatex: "S \\propto V^{2/3}\\text{ for a sphere};\\;\\;\\displaystyle\\frac{dV}{dt} \\propto -S \\propto -V^{2/3}", explanation: "For a sphere, \\(V = \\displaystyle\\frac{4}{3}\\pi r^{3}\\) and \\(S = 4\\pi r^{2}\\), so \\(S \\propto V^{2/3}\\). Melting that scales with exposed surface area therefore gives \\(\\displaystyle\\frac{dV}{dt} = -kV^{2/3}\\)." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Separable, power law on the right.}", explanation: "All \\(V\\)-dependence is in \\(V^{2/3}\\) and the \\(t\\)-side is just \\(-k\\,dt\\) — clean separation." }, { stepNumber: 3, description: "Separate the variables.", workingLatex: "V^{-2/3}\\,dV = -k\\,dt", explanation: "Divide through by \\(V^{2/3}\\) and multiply by \\(dt\\). Each side is now in a single variable." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int V^{-2/3}\\,dV = \\displaystyle\\int -k\\,dt \\;\\Rightarrow\\; \\displaystyle\\frac{V^{1/3}}{1/3} = -kt + C \\;\\Rightarrow\\; 3V^{1/3} = -kt + C", explanation: "Power-rule integration: \\(\\displaystyle\\int V^{n}\\,dV = \\displaystyle\\frac{V^{n+1}}{n+1}\\) with \\(n = -\\displaystyle\\frac{2}{3}\\), giving \\(\\displaystyle\\frac{V^{1/3}}{1/3} = 3V^{1/3}\\)." }, { stepNumber: 5, description: "Apply the initial condition \\(V(0) = V_0\\).", workingLatex: "3V_0^{1/3} = C \\;\\Rightarrow\\; 3V^{1/3} = -kt + 3V_0^{1/3}", explanation: "Substituting \\(t = 0\\) pins the constant of integration to the initial cube-root." }, { stepNumber: 6, description: "Solve for the cube-root of \\(V\\) explicitly.", workingLatex: "V^{1/3} = V_0^{1/3} - \\displaystyle\\frac{kt}{3}", explanation: "Divide by \\(3\\). The cube-root of the volume decreases linearly in \\(t\\) — a hallmark of surface-area-driven shrinking." }, { stepNumber: 7, description: "Cube to obtain \\(V(t)\\).", workingLatex: "V(t) = \\left(V_0^{1/3} - \\displaystyle\\frac{kt}{3}\\right)^{3}", explanation: "Raising both sides to the cube undoes the cube-root and exposes the explicit decay curve." }, { stepNumber: 8, description: "Verify by differentiating.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 3\\left(V_0^{1/3} - \\displaystyle\\frac{kt}{3}\\right)^{2}\\cdot\\left(-\\displaystyle\\frac{k}{3}\\right) = -k\\left(V_0^{1/3} - \\displaystyle\\frac{kt}{3}\\right)^{2} = -kV^{2/3} \\;\\checkmark", explanation: "Chain rule: the inner \\(-\\displaystyle\\frac{k}{3}\\) and the outer \\(3\\) cancel cleanly, and \\(\\left(V^{1/3}\\right)^{2} = V^{2/3}\\), recovering the original DE." } ], finalAnswer: "\\(V(t) = \\left(V_0^{\\frac{1}{3}} - \\displaystyle\\frac{kt}{3}\\right)^3\\)." } },
  { id: "y2in10-052", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 52", difficulty: "Standard", questionText: "From previous, find the time for the snowball to completely melt.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "State the explicit solution from the previous part.", workingLatex: "V(t) = \\left(V_0^{1/3} - \\displaystyle\\frac{kt}{3}\\right)^{3}", explanation: "Carry the explicit form across — the volume curve has a definite finite-time zero." }, { stepNumber: 2, description: "Set \\(V(t) = 0\\) to find the melt time.", workingLatex: "\\left(V_0^{1/3} - \\displaystyle\\frac{kt}{3}\\right)^{3} = 0 \\;\\Rightarrow\\; V_0^{1/3} - \\displaystyle\\frac{kt}{3} = 0", explanation: "A cube equals zero only when its base equals zero — so the bracket itself must vanish." }, { stepNumber: 3, description: "Solve for \\(t\\).", workingLatex: "\\displaystyle\\frac{kt}{3} = V_0^{1/3} \\;\\Rightarrow\\; t = \\displaystyle\\frac{3V_0^{1/3}}{k}", explanation: "Multiply by \\(3\\) and divide by \\(k\\). The melt time is proportional to the initial cube-root of the volume, i.e. to the initial radius — physically sensible since a sphere shrinks at a rate fixed by its surface." }, { stepNumber: 4, description: "Verify by substituting back.", workingLatex: "V\\!\\left(\\displaystyle\\frac{3V_0^{1/3}}{k}\\right) = \\left(V_0^{1/3} - \\displaystyle\\frac{k}{3}\\cdot\\displaystyle\\frac{3V_0^{1/3}}{k}\\right)^{3} = 0 \\;\\checkmark", explanation: "Substituting confirms the snowball vanishes exactly at this time." } ], finalAnswer: "\\(t = \\displaystyle\\frac{3V_0^{\\frac{1}{3}}}{k}\\)." } },
  { id: "y2in10-053", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 53", difficulty: "Standard", questionText: "\\(\\displaystyle\\frac{dV}{dt} = 5 - 0.1V\\), \\(V(0) = 20\\). Find \\(V(20)\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the DE type and the steady state.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 5 - 0.1V \\;\\Rightarrow\\; V^{*} = 50", explanation: "A linear first-order DE of the form \\(V' = a - bV\\). Setting \\(V' = 0\\) gives the equilibrium \\(V^{*} = a/b = 5/0.1 = 50\\) — the long-term value." }, { stepNumber: 2, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dV}{5 - 0.1V} = dt", explanation: "Treat the right-hand side as a function of \\(V\\) only and isolate \\(dV\\) from \\(dt\\)." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dV}{5 - 0.1V} = \\displaystyle\\int dt \\;\\Rightarrow\\; -\\displaystyle\\frac{1}{0.1}\\ln|5 - 0.1V| = t + C \\;\\Rightarrow\\; -10\\ln|5 - 0.1V| = t + C", explanation: "Use \\(\\displaystyle\\int \\displaystyle\\frac{dV}{a - bV} = -\\displaystyle\\frac{1}{b}\\ln|a - bV|\\). Here \\(b = 0.1\\), giving the leading \\(-10\\)." }, { stepNumber: 4, description: "Solve for \\(V\\).", workingLatex: "\\ln|5 - 0.1V| = -\\displaystyle\\frac{t}{10} + C' \\;\\Rightarrow\\; 5 - 0.1V = Ae^{-t/10} \\;\\Rightarrow\\; V = 50 - 10Ae^{-t/10}", explanation: "Exponentiate, absorb the constant into \\(A\\), then solve for \\(V\\). The structure \\(V = V^{*} + \\text{(decay term)}\\) is the canonical form." }, { stepNumber: 5, description: "Apply IC \\(V(0) = 20\\).", workingLatex: "20 = 50 - 10A \\;\\Rightarrow\\; 10A = 30 \\;\\Rightarrow\\; 10A = 30", explanation: "Substituting \\(t = 0\\) collapses the exponential to \\(1\\) and the constant emerges as \\(10A = 30\\)." }, { stepNumber: 6, description: "Write the explicit solution.", workingLatex: "V(t) = 50 - 30e^{-t/10}", explanation: "Decay towards the steady state \\(50\\) from below, with the gap \\(30\\) at \\(t = 0\\) shrinking exponentially." }, { stepNumber: 7, description: "Evaluate at \\(t = 20\\).", workingLatex: "V(20) = 50 - 30e^{-2} = 50 - 30(0.1353\\ldots) \\approx 50 - 4.060 \\approx 45.94", explanation: "Using \\(e^{-2} \\approx 0.1353\\), the second term contributes about \\(4.06\\), leaving \\(V(20) \\approx 45.94\\)." }, { stepNumber: 8, description: "Verify by substituting into the DE.", workingLatex: "\\displaystyle\\frac{dV}{dt} = 3e^{-t/10};\\;\\; 5 - 0.1V = 5 - 5 + 3e^{-t/10} = 3e^{-t/10} \\;\\checkmark", explanation: "Both sides agree, confirming the solution is correct." } ], finalAnswer: "\\(V(20) = 50 - 30e^{-2} \\approx 45.94\\)." } },
  { id: "y2in10-054", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 54", difficulty: "Standard", questionText: "Find the concentration \\(C\\) after 6 hours given \\(C = 50\\left(1 - e^{-0.1t}\\right)\\) (from q29).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "C(t) = 50\\!\\left(1 - e^{-0.1t}\\right)", explanation: "A standard saturation curve: \\(C\\) rises from \\(0\\) at \\(t = 0\\) towards the asymptotic ceiling \\(50\\) (mg) as \\(t \\to \\infty\\); the parameter \\(0.1\\) controls how quickly it approaches that ceiling." }, { stepNumber: 2, description: "Substitute \\(t = 6\\).", workingLatex: "C(6) = 50\\!\\left(1 - e^{-0.1\\cdot 6}\\right) = 50\\!\\left(1 - e^{-0.6}\\right)", explanation: "Plug \\(t = 6\\) directly into the formula — no further setup required." }, { stepNumber: 3, description: "Evaluate the exponential.", workingLatex: "e^{-0.6} \\approx 0.5488", explanation: "Calculator value." }, { stepNumber: 4, description: "Compute the bracket.", workingLatex: "1 - e^{-0.6} \\approx 1 - 0.5488 = 0.4512", explanation: "About \\(45\\%\\) of the way to saturation after \\(6\\) hours." }, { stepNumber: 5, description: "Multiply by \\(50\\) and state the answer.", workingLatex: "C(6) \\approx 50 \\cdot 0.4512 \\approx 22.56\\text{ mg}", explanation: "The concentration after \\(6\\) hours is about \\(22.56\\) mg — well below the long-term ceiling of \\(50\\) mg." }, { stepNumber: 6, description: "Sanity check.", workingLatex: "0 < 22.56 < 50 \\;\\checkmark", explanation: "Value sits within the physically expected range, with the curve still well below saturation." } ], finalAnswer: "\\(C(6) \\approx 22.56\\) mg." } },
  { id: "y2in10-055", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 55", difficulty: "Challenge", questionText: "An annuity pays £1000 per year continuously while earning 4%: \\(\\displaystyle\\frac{dA}{dt} = 0.04A - 1000\\), \\(A(0) = 20000\\). Find when \\(A = 0\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dA}{dt} = 0.04A - 1000", explanation: "The \\(0.04A\\) term is continuous compounding at \\(4\\%\\); the \\(-1000\\) is the continuous annual payment. The sign of the net derivative determines whether the account grows or shrinks." }, { stepNumber: 2, description: "Find the unstable equilibrium.", workingLatex: "0 = 0.04A^{*} - 1000 \\;\\Rightarrow\\; A^{*} = 25000", explanation: "At \\(A = 25000\\) the interest exactly funds the payment. Below \\(25000\\) the payments outstrip interest and \\(A\\) decreases — relevant here since \\(A(0) = 20000 < 25000\\)." }, { stepNumber: 3, description: "Separate variables.", workingLatex: "\\displaystyle\\frac{dA}{0.04A - 1000} = dt", explanation: "Move all \\(A\\)-dependence to one side. The structure is again \\(V' = aV - b\\) (linear first-order)." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\frac{1}{0.04}\\ln|0.04A - 1000| = t + C \\;\\Rightarrow\\; 25\\ln|0.04A - 1000| = t + C", explanation: "\\(\\displaystyle\\int \\displaystyle\\frac{dA}{0.04A - 1000} = \\displaystyle\\frac{1}{0.04}\\ln|0.04A - 1000|\\); the factor \\(1/0.04 = 25\\)." }, { stepNumber: 5, description: "Solve for \\(A\\) and apply IC \\(A(0) = 20000\\).", workingLatex: "0.04A - 1000 = Be^{t/25};\\; A = 25000 + 25Be^{t/25};\\; 20000 = 25000 + 25B \\Rightarrow B = -200", explanation: "Exponentiate, absorb constants into \\(B\\), and substitute \\(t = 0\\). The negative \\(B\\) reflects the account being below the equilibrium." }, { stepNumber: 6, description: "Write the explicit solution.", workingLatex: "A(t) = 25000 - 5000\\,e^{0.04t}", explanation: "Note \\(25B = -5000\\) and \\(e^{t/25} = e^{0.04t}\\). The account decreases as the negative exponential grows." }, { stepNumber: 7, description: "Set \\(A = 0\\) and solve for \\(t\\).", workingLatex: "0 = 25000 - 5000\\,e^{0.04t} \\;\\Rightarrow\\; e^{0.04t} = 5 \\;\\Rightarrow\\; t = \\displaystyle\\frac{\\ln 5}{0.04}", explanation: "Move terms across, divide, and take logs. The annuity is exhausted when the negative term has grown five-fold." }, { stepNumber: 8, description: "Evaluate numerically and verify.", workingLatex: "t = \\displaystyle\\frac{\\ln 5}{0.04} \\approx \\displaystyle\\frac{1.6094}{0.04} \\approx 40.24 \\text{ years}", explanation: "Check: \\(A(40.24) = 25000 - 5000 e^{1.6094} = 25000 - 5000\\cdot 5 = 0\\). The annuity lasts about \\(40\\) years." } ], finalAnswer: "\\(t \\approx 40.2\\) years." } },
  { id: "y2in10-056", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 56", difficulty: "Standard", questionText: "An oil spill spreads so its area increases at rate proportional to \\(\\sqrt A\\): \\(\\displaystyle\\frac{dA}{dt} = k\\sqrt A\\). Solve for \\(A(t)\\) with \\(A(0) = A_0\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dA}{dt} = k\\sqrt A", explanation: "Spread rate scaling with \\(\\sqrt A\\) is geometrically reasonable: \\(\\sqrt A\\) is essentially a linear dimension (radius), so the perimeter — where most of the spreading happens — is proportional to \\(\\sqrt A\\)." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Separable, power-law right-hand side.}", explanation: "The \\(A\\)-dependence is \\(\\sqrt A = A^{1/2}\\) and the \\(t\\)-side is constant — clean separation." }, { stepNumber: 3, description: "Separate variables.", workingLatex: "A^{-1/2}\\,dA = k\\,dt", explanation: "Divide by \\(\\sqrt A\\) and multiply by \\(dt\\)." }, { stepNumber: 4, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int A^{-1/2}\\,dA = \\displaystyle\\int k\\,dt \\;\\Rightarrow\\; 2A^{1/2} = kt + C", explanation: "Power rule: \\(\\displaystyle\\int A^{-1/2}\\,dA = 2A^{1/2}\\); the right-hand side integrates trivially." }, { stepNumber: 5, description: "Apply IC \\(A(0) = A_{0}\\).", workingLatex: "2\\sqrt{A_0} = C \\;\\Rightarrow\\; 2\\sqrt A = kt + 2\\sqrt{A_0}", explanation: "Substituting \\(t = 0\\) pins the constant to twice the initial root-area." }, { stepNumber: 6, description: "Solve for \\(\\sqrt A\\).", workingLatex: "\\sqrt A = \\sqrt{A_0} + \\displaystyle\\frac{kt}{2}", explanation: "Divide by \\(2\\). The square-root of the area grows linearly in \\(t\\) — meaning the radius (effectively) grows at a constant rate." }, { stepNumber: 7, description: "Square to obtain \\(A(t)\\).", workingLatex: "A(t) = \\left(\\sqrt{A_0} + \\displaystyle\\frac{kt}{2}\\right)^{2}", explanation: "Squaring undoes the root and gives the explicit area function." }, { stepNumber: 8, description: "Verify by differentiating.", workingLatex: "\\displaystyle\\frac{dA}{dt} = 2\\!\\left(\\sqrt{A_0} + \\displaystyle\\frac{kt}{2}\\right)\\cdot \\displaystyle\\frac{k}{2} = k\\!\\left(\\sqrt{A_0} + \\displaystyle\\frac{kt}{2}\\right) = k\\sqrt A \\;\\checkmark", explanation: "Chain rule reproduces the original DE exactly, confirming the antiderivative." } ], finalAnswer: "\\(A(t) = \\left(\\sqrt{A_0} + \\displaystyle\\frac{kt}{2}\\right)^2\\)." } },
  { id: "y2in10-057", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 57", difficulty: "Standard", questionText: "Cake at 25°C placed in 180°C oven: \\(\\displaystyle\\frac{dT}{dt} = -k(T - 180)\\). If \\(T\\) reaches 100°C in 10 min, find \\(k\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model — Newton's law of heating.", workingLatex: "\\displaystyle\\frac{dT}{dt} = -k(T - 180)", explanation: "Rate of temperature change is proportional to the gap between the cake and the oven (\\(180\\) °C). The minus sign and the form of the gap force \\(T\\) to chase the oven temperature." }, { stepNumber: 2, description: "Identify the DE type.", workingLatex: "\\text{Linear first-order, separable, with stable equilibrium } T^{*} = 180.", explanation: "Newton-of-cooling/heating template — same maths regardless of whether the body is warmer or cooler than its surroundings." }, { stepNumber: 3, description: "Separate variables and integrate.", workingLatex: "\\displaystyle\\frac{dT}{T - 180} = -k\\,dt \\;\\Rightarrow\\; \\ln|T - 180| = -kt + C", explanation: "Move \\(T\\)-dependence to one side and integrate both sides; standard log antiderivative on the left." }, { stepNumber: 4, description: "Exponentiate and apply IC \\(T(0) = 25\\).", workingLatex: "T - 180 = Ae^{-kt};\\; 25 - 180 = A \\Rightarrow A = -155;\\;\\; T - 180 = -155 e^{-kt}", explanation: "Substituting \\(t = 0\\) gives \\(A = -155\\). The temperature gap starts at \\(-155\\) and decays exponentially towards zero." }, { stepNumber: 5, description: "Apply the second data point \\(T(10) = 100\\).", workingLatex: "100 - 180 = -155 e^{-10k} \\;\\Rightarrow\\; -80 = -155 e^{-10k} \\;\\Rightarrow\\; e^{-10k} = \\displaystyle\\frac{80}{155}", explanation: "Substitute \\(t = 10\\) and \\(T = 100\\). The minus signs cancel and we isolate the exponential." }, { stepNumber: 6, description: "Solve for \\(k\\) using logarithms.", workingLatex: "-10k = \\ln\\!\\left(\\displaystyle\\frac{80}{155}\\right) \\;\\Rightarrow\\; k = \\displaystyle\\frac{1}{10}\\ln\\!\\left(\\displaystyle\\frac{155}{80}\\right)", explanation: "Take the natural log of both sides, flip the fraction inside the log to remove the leading minus, and divide by \\(10\\)." }, { stepNumber: 7, description: "Evaluate numerically.", workingLatex: "k = \\displaystyle\\frac{\\ln(1.9375)}{10} \\approx \\displaystyle\\frac{0.6614}{10} \\approx 0.0661 \\text{ min}^{-1}", explanation: "Calculator value. The decay constant of about \\(0.066\\) per minute is consistent with a cake heating noticeably but not instantaneously." }, { stepNumber: 8, description: "Verify.", workingLatex: "T(10) = 180 - 155 e^{-0.661} \\approx 180 - 155 \\cdot 0.5161 \\approx 100 \\;\\checkmark", explanation: "Substituting \\(k\\) back recovers \\(T(10) = 100\\), confirming the rate constant." } ], finalAnswer: "\\(k = \\displaystyle\\frac{\\ln(155/80)}{10} \\approx 0.0661\\)." } },
  { id: "y2in10-058", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 58", difficulty: "Challenge", questionText: "Solve \\(\\displaystyle\\frac{dP}{dt} = 0.05P - 100\\), \\(P(0) = 1500\\). What happens long-term?", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = 0.05P - 100", explanation: "Population grows at \\(5\\%\\) per unit time but loses a constant \\(100\\) individuals per unit time (e.g. harvesting). Whether \\(P\\) grows or shrinks depends on its size relative to the equilibrium." }, { stepNumber: 2, description: "Find the (unstable) equilibrium.", workingLatex: "0 = 0.05P^{*} - 100 \\;\\Rightarrow\\; P^{*} = 2000", explanation: "Above \\(P = 2000\\) growth dominates and the population explodes; below it, harvesting wins and the population declines towards extinction. The IC \\(P(0) = 1500 < 2000\\) places us in the declining regime." }, { stepNumber: 3, description: "Separate and integrate.", workingLatex: "\\displaystyle\\frac{dP}{0.05P - 100} = dt \\;\\Rightarrow\\; \\displaystyle\\frac{1}{0.05}\\ln|0.05P - 100| = t + C", explanation: "Standard log-antiderivative; \\(1/0.05 = 20\\)." }, { stepNumber: 4, description: "Exponentiate and tidy.", workingLatex: "0.05P - 100 = Ae^{0.05t} \\;\\Rightarrow\\; P = 2000 + 20Ae^{0.05t}", explanation: "Absorb constants into \\(A\\); the structure is \\(P = P^{*} + \\text{growth term}\\)." }, { stepNumber: 5, description: "Apply IC \\(P(0) = 1500\\).", workingLatex: "1500 = 2000 + 20A \\;\\Rightarrow\\; 20A = -500 \\;\\Rightarrow\\; 20A = -500", explanation: "Substituting \\(t = 0\\) and solving gives the constant \\(20A = -500\\) — the negative sign signals the population starts below the unstable equilibrium." }, { stepNumber: 6, description: "Write the explicit solution.", workingLatex: "P(t) = 2000 - 500\\,e^{0.05t}", explanation: "The negative exponential term grows without bound, dragging \\(P\\) below the equilibrium and eventually to zero." }, { stepNumber: 7, description: "Find the extinction time \\(P = 0\\).", workingLatex: "0 = 2000 - 500\\,e^{0.05t} \\;\\Rightarrow\\; e^{0.05t} = 4 \\;\\Rightarrow\\; t = \\displaystyle\\frac{\\ln 4}{0.05} = 20\\ln 4", explanation: "Solve \\(500e^{0.05t} = 2000\\) and take logs. The extinction time is \\(20\\ln 4 = 40\\ln 2 \\approx 27.73\\)." }, { stepNumber: 8, description: "Interpret in context and verify.", workingLatex: "P(27.73) = 2000 - 500\\cdot e^{0.05\\cdot 27.73} = 2000 - 500\\cdot 4 = 0 \\;\\checkmark", explanation: "Long-term: the population goes extinct at \\(t \\approx 27.7\\); the unstable equilibrium at \\(P = 2000\\) means any population starting below it is doomed under this model." } ], finalAnswer: "Population goes extinct at \\(t \\approx 27.7\\)." } },
  { id: "y2in10-059", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 59", difficulty: "Challenge", questionText: "A quantity \\(Q\\) satisfies \\(\\displaystyle\\frac{dQ}{dP} = -\\displaystyle\\frac{Q}{P}\\). Solve.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dQ}{dP} = -\\displaystyle\\frac{Q}{P}", explanation: "An economist's unit-elastic demand curve: the percentage change in \\(Q\\) equals minus the percentage change in \\(P\\). Equivalently, the price elasticity of demand is exactly \\(-1\\)." }, { stepNumber: 2, description: "Identify the DE type and separate.", workingLatex: "\\displaystyle\\frac{dQ}{Q} = -\\displaystyle\\frac{dP}{P}", explanation: "Both sides isolate cleanly — separable first-order. The symmetry of the variables is built into the unit-elasticity statement." }, { stepNumber: 3, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{dQ}{Q} = -\\displaystyle\\int \\displaystyle\\frac{dP}{P} \\;\\Rightarrow\\; \\ln|Q| = -\\ln|P| + C", explanation: "Standard log antiderivatives. The integration constant is denoted \\(C\\)." }, { stepNumber: 4, description: "Exponentiate.", workingLatex: "|Q| = e^{C}\\cdot |P|^{-1} \\;\\Rightarrow\\; Q = \\displaystyle\\frac{A}{P}", explanation: "Absorbing \\(e^{C}\\) (and possible sign) into a single constant \\(A\\) gives the rectangular-hyperbola family of solutions." }, { stepNumber: 5, description: "Interpret economically.", workingLatex: "Q \\cdot P = A = \\text{constant}", explanation: "Revenue \\(QP\\) is constant along the demand curve — the hallmark of unit-elastic demand." }, { stepNumber: 6, description: "Verify by differentiation.", workingLatex: "Q = \\displaystyle\\frac{A}{P} \\;\\Rightarrow\\; \\displaystyle\\frac{dQ}{dP} = -\\displaystyle\\frac{A}{P^{2}} = -\\displaystyle\\frac{1}{P}\\cdot \\displaystyle\\frac{A}{P} = -\\displaystyle\\frac{Q}{P} \\;\\checkmark", explanation: "Differentiating recovers the original DE — the family \\(Q = A/P\\) is indeed the general solution." } ], finalAnswer: "\\(Q = \\displaystyle\\frac{A}{P}\\) (unit-elastic demand)." } },
  { id: "y2in10-060", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 60", difficulty: "Challenge", questionText: "Given \\(\\displaystyle\\frac{dv}{dt} = -\\omega^2 x\\) and \\(v = \\displaystyle\\frac{dx}{dt}\\), show \\(v^2 + \\omega^2 x^2\\) is constant (energy conservation).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model — simple harmonic motion.", workingLatex: "\\displaystyle\\frac{dv}{dt} = -\\omega^{2} x;\\;\\; v = \\displaystyle\\frac{dx}{dt}", explanation: "The acceleration \\(dv/dt\\) is proportional to displacement and points back towards equilibrium — Hooke's law / SHM. We will extract an energy-conservation law without explicitly solving for \\(x(t)\\)." }, { stepNumber: 2, description: "Apply the chain-rule trick to rewrite the DE.", workingLatex: "\\displaystyle\\frac{dv}{dt} = \\displaystyle\\frac{dv}{dx}\\cdot\\displaystyle\\frac{dx}{dt} = v\\,\\displaystyle\\frac{dv}{dx}", explanation: "Standard manoeuvre when the right-hand side depends on the spatial variable: convert \\(t\\)-derivatives into \\(x\\)-derivatives by chaining through \\(v\\)." }, { stepNumber: 3, description: "Write the DE in \\(x\\)-form.", workingLatex: "v\\,\\displaystyle\\frac{dv}{dx} = -\\omega^{2} x", explanation: "Equate the two expressions for \\(dv/dt\\). Now everything is a function of \\(x\\)." }, { stepNumber: 4, description: "Separate variables.", workingLatex: "v\\,dv = -\\omega^{2} x\\,dx", explanation: "Multiply both sides by \\(dx\\). Each side now contains only one variable." }, { stepNumber: 5, description: "Integrate both sides.", workingLatex: "\\displaystyle\\int v\\,dv = -\\omega^{2}\\displaystyle\\int x\\,dx \\;\\Rightarrow\\; \\displaystyle\\frac{v^{2}}{2} = -\\displaystyle\\frac{\\omega^{2} x^{2}}{2} + C", explanation: "Power-rule antiderivatives; the constant absorbs the integration constants from both sides." }, { stepNumber: 6, description: "Rearrange into the conservation form.", workingLatex: "\\displaystyle\\frac{v^{2}}{2} + \\displaystyle\\frac{\\omega^{2} x^{2}}{2} = C \\;\\Rightarrow\\; v^{2} + \\omega^{2} x^{2} = 2C", explanation: "Move the \\(x^{2}\\) term across and multiply by \\(2\\). The combination \\(v^{2} + \\omega^{2} x^{2}\\) — proportional to total energy (kinetic + potential) — is independent of \\(t\\)." }, { stepNumber: 7, description: "Verify by direct differentiation in \\(t\\).", workingLatex: "\\displaystyle\\frac{d}{dt}\\!\\left(v^{2} + \\omega^{2} x^{2}\\right) = 2v\\,\\displaystyle\\frac{dv}{dt} + 2\\omega^{2}x\\,\\displaystyle\\frac{dx}{dt} = 2v(-\\omega^{2}x) + 2\\omega^{2}x\\,v = 0 \\;\\checkmark", explanation: "The derivative vanishes identically, confirming \\(v^{2} + \\omega^{2} x^{2}\\) is constant in time — energy conservation for SHM." } ], finalAnswer: "\\(v^2 + \\omega^2 x^2 = 2C\\) (constant). \\(\\blacksquare\\)" } },
  { id: "y2in10-061", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 61", difficulty: "Standard", questionText: "A drug has half-life 6 hours. Find the time for 10% to remain.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the half-life.", workingLatex: "M(t) = M_{0}\\!\\left(\\displaystyle\\frac{1}{2}\\right)^{t/6}", explanation: "Each \\(6\\)-hour window multiplies the surviving fraction by \\(\\displaystyle\\frac{1}{2}\\). Working with base \\(\\displaystyle\\frac{1}{2}\\) makes the half-life data plug in directly without computing a separate decay constant." }, { stepNumber: 2, description: "Set the surviving fraction to \\(10\\%\\).", workingLatex: "\\displaystyle\\frac{M}{M_{0}} = 0.1 \\;\\Rightarrow\\; \\left(\\displaystyle\\frac{1}{2}\\right)^{t/6} = 0.1", explanation: "Divide both sides of the model by \\(M_{0}\\) and equate to the desired surviving fraction." }, { stepNumber: 3, description: "Take natural logs of both sides.", workingLatex: "\\displaystyle\\frac{t}{6}\\ln\\!\\left(\\displaystyle\\frac{1}{2}\\right) = \\ln(0.1) \\;\\Rightarrow\\; -\\displaystyle\\frac{t}{6}\\ln 2 = -\\ln 10", explanation: "Use \\(\\ln(1/2) = -\\ln 2\\) and \\(\\ln(0.1) = -\\ln 10\\); both sides carry a minus, which cancels." }, { stepNumber: 4, description: "Solve for \\(t\\).", workingLatex: "t = \\displaystyle\\frac{6\\ln 10}{\\ln 2}", explanation: "Multiply by \\(6\\) and divide by \\(\\ln 2\\) — the closed form of the answer." }, { stepNumber: 5, description: "Evaluate numerically.", workingLatex: "t \\approx \\displaystyle\\frac{6 \\cdot 2.3026}{0.6931} \\approx \\displaystyle\\frac{13.816}{0.6931} \\approx 19.93 \\text{ h}", explanation: "Calculator values \\(\\ln 10 \\approx 2.3026\\), \\(\\ln 2 \\approx 0.6931\\). The answer is just under \\(20\\) hours — slightly more than three half-lives, consistent with \\((1/2)^{3} = 0.125 > 0.1\\)." }, { stepNumber: 6, description: "Verify.", workingLatex: "(1/2)^{19.93/6} = (1/2)^{3.322} \\approx 0.0999 \\;\\checkmark", explanation: "Substituting back recovers the target \\(10\\%\\) surviving fraction." } ], finalAnswer: "\\(t = \\displaystyle\\frac{6\\ln 10}{\\ln 2} \\approx 19.93\\) hours." } },
  { id: "y2in10-062", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 62", difficulty: "Challenge", questionText: "Solve \\(\\displaystyle\\frac{dy}{dt} + y = \\sin t\\), \\(y(0) = 0\\). Interpret the solution for large \\(t\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the DE type — linear with integrating factor.", workingLatex: "\\displaystyle\\frac{dy}{dt} + P(t)y = Q(t),\\;\\; P(t) = 1,\\;\\; Q(t) = \\sin t", explanation: "Linear first-order with constant coefficient \\(P = 1\\); the right-hand side is the forcing. The standard recipe uses an integrating factor." }, { stepNumber: 2, description: "Compute the integrating factor.", workingLatex: "\\mu(t) = e^{\\int 1\\,dt} = e^{t}", explanation: "\\(\\mu = e^{\\int P\\,dt}\\) — here just \\(e^{t}\\)." }, { stepNumber: 3, description: "Multiply through and collapse the LHS.", workingLatex: "e^{t}\\,\\displaystyle\\frac{dy}{dt} + e^{t}\\,y = e^{t}\\sin t \\;\\Rightarrow\\; \\displaystyle\\frac{d}{dt}\\!\\left(e^{t}y\\right) = e^{t}\\sin t", explanation: "By the product rule the left-hand side is exactly \\(d(\\mu y)/dt\\). That is the whole point of the integrating factor." }, { stepNumber: 4, description: "Integrate the RHS using the standard formula.", workingLatex: "\\displaystyle\\int e^{t}\\sin t\\,dt = \\displaystyle\\frac{e^{t}(\\sin t - \\cos t)}{2} + K", explanation: "Standard antiderivative (two integration-by-parts steps, or use the result \\(\\displaystyle\\int e^{at}\\sin bt\\,dt = \\displaystyle\\frac{e^{at}(a\\sin bt - b\\cos bt)}{a^{2}+b^{2}}\\) with \\(a = b = 1\\))." }, { stepNumber: 5, description: "Divide by \\(\\mu = e^{t}\\) and apply IC.", workingLatex: "y = \\displaystyle\\frac{\\sin t - \\cos t}{2} + K e^{-t};\\;\\; y(0) = 0 \\Rightarrow 0 = \\displaystyle\\frac{0 - 1}{2} + K \\Rightarrow K = \\displaystyle\\frac{1}{2}", explanation: "Substituting \\(t = 0\\) into the general solution fixes \\(K = \\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 6, description: "Write the explicit solution.", workingLatex: "y(t) = \\displaystyle\\frac{\\sin t - \\cos t}{2} + \\displaystyle\\frac{e^{-t}}{2}", explanation: "Sum of a steady oscillatory response and a transient that decays as \\(e^{-t}\\)." }, { stepNumber: 7, description: "Interpret for large \\(t\\).", workingLatex: "y(t) \\to \\displaystyle\\frac{\\sin t - \\cos t}{2} = \\displaystyle\\frac{\\sqrt 2}{2}\\sin\\!\\left(t - \\displaystyle\\frac{\\pi}{4}\\right)", explanation: "The exponential transient vanishes. Using the \\(R\\sin(t + \\varphi)\\) form, \\(\\displaystyle\\frac{1}{2}\\sin t - \\displaystyle\\frac{1}{2}\\cos t = \\displaystyle\\frac{\\sqrt 2}{2}\\sin(t - \\pi/4)\\). Steady-state amplitude \\(\\sqrt 2/2\\), lagging the forcing by \\(\\pi/4\\)." }, { stepNumber: 8, description: "Verify by substituting back.", workingLatex: "y' = \\displaystyle\\frac{\\cos t + \\sin t}{2} - \\displaystyle\\frac{e^{-t}}{2};\\;\\; y' + y = \\displaystyle\\frac{\\cos t + \\sin t}{2} - \\displaystyle\\frac{e^{-t}}{2} + \\displaystyle\\frac{\\sin t - \\cos t}{2} + \\displaystyle\\frac{e^{-t}}{2} = \\sin t \\;\\checkmark", explanation: "All transient and cosine terms cancel, leaving exactly \\(\\sin t\\) — confirms the solution." } ], finalAnswer: "\\(y = \\displaystyle\\frac{\\sin t - \\cos t}{2} + \\displaystyle\\frac{e^{-t}}{2}\\); long-term: \\(\\displaystyle\\frac{\\sqrt 2}{2}\\sin(t - \\pi/4)\\)." } },
  { id: "y2in10-063", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 63", difficulty: "Standard", questionText: "A lake has initial 200 g of radioactive material with decay rate \\(0.05\\)/yr and no removal otherwise. Find the amount after 20 years.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dM}{dt} = -0.05\\,M", explanation: "First-order radioactive decay: rate of loss proportional to amount remaining. The decay constant is \\(0.05\\)/yr." }, { stepNumber: 2, description: "Identify the DE type and integrate.", workingLatex: "\\displaystyle\\frac{dM}{M} = -0.05\\,dt \\;\\Rightarrow\\; \\ln M = -0.05\\,t + C", explanation: "Separable; standard log antiderivative on the left." }, { stepNumber: 3, description: "Exponentiate.", workingLatex: "M(t) = M_{0}\\,e^{-0.05 t}", explanation: "Absorb \\(e^{C}\\) into \\(M_{0}\\); the canonical exponential-decay form." }, { stepNumber: 4, description: "Apply IC \\(M(0) = 200\\).", workingLatex: "M(t) = 200\\,e^{-0.05 t}", explanation: "Substituting \\(t = 0\\) confirms the multiplicative constant is the initial mass \\(200\\) g." }, { stepNumber: 5, description: "Evaluate at \\(t = 20\\).", workingLatex: "M(20) = 200\\,e^{-0.05\\cdot 20} = 200\\,e^{-1}", explanation: "The exponent becomes exactly \\(-1\\) after \\(20\\) years — one \"e-folding time\"." }, { stepNumber: 6, description: "Numerical value.", workingLatex: "M(20) = \\displaystyle\\frac{200}{e} \\approx 200 \\cdot 0.3679 \\approx 73.58 \\text{ g}", explanation: "Using \\(e \\approx 2.718\\); about \\(37\\%\\) of the original mass remains." }, { stepNumber: 7, description: "Sanity check.", workingLatex: "\\text{Half-life } = \\displaystyle\\frac{\\ln 2}{0.05} \\approx 13.86 \\text{ yr};\\;\\; 20\\text{ yr} > T_{1/2} \\Rightarrow M < 100", explanation: "Consistent: after more than one half-life, the surviving mass is below \\(100\\) g." } ], finalAnswer: "\\(\\approx 73.58\\) g." } },
  { id: "y2in10-064", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 64", difficulty: "Foundation", questionText: "A bank account grows continuously at 3%. Initial £5000. Find its value after 20 years.", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dA}{dt} = 0.03\\,A", explanation: "Continuous compounding at \\(3\\%\\) — the standard exponential growth model for instantaneous interest accrual." }, { stepNumber: 2, description: "Write the explicit solution.", workingLatex: "A(t) = A_{0}\\,e^{0.03 t}", explanation: "Standard exponential-growth integral with rate \\(0.03\\); IC \\(A(0) = A_{0}\\)." }, { stepNumber: 3, description: "Substitute \\(A_{0} = 5000\\) and \\(t = 20\\).", workingLatex: "A(20) = 5000\\,e^{0.03\\cdot 20} = 5000\\,e^{0.6}", explanation: "The exponent reduces cleanly to \\(0.6\\)." }, { stepNumber: 4, description: "Evaluate and state.", workingLatex: "A(20) \\approx 5000 \\cdot 1.8221 \\approx \\pounds 9110.59", explanation: "\\(e^{0.6} \\approx 1.8221\\); the balance after \\(20\\) years is about \\(\\pounds 9110.59\\) — roughly an \\(82\\%\\) gain on the principal." } ], finalAnswer: "\\(\\approx £9110.59\\)." } },
  { id: "y2in10-065", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 65", difficulty: "Standard", questionText: "Water at 100°C in a room at 20°C cools by Newton's law. It reaches 60°C after 20 minutes. Find the time to reach 30°C.", marks: 5, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model — Newton's law of cooling.", workingLatex: "\\displaystyle\\frac{dT}{dt} = -k(T - 20)", explanation: "Cooling rate proportional to the temperature gap above the room (\\(20\\) °C). The room temperature is the asymptote." }, { stepNumber: 2, description: "Separate and integrate.", workingLatex: "\\displaystyle\\frac{dT}{T - 20} = -k\\,dt \\;\\Rightarrow\\; \\ln|T - 20| = -kt + C", explanation: "Separable; standard log antiderivative." }, { stepNumber: 3, description: "Exponentiate and apply IC \\(T(0) = 100\\).", workingLatex: "T - 20 = 80\\,e^{-kt}", explanation: "Initial gap is \\(100 - 20 = 80\\); the gap shrinks exponentially." }, { stepNumber: 4, description: "Use \\(T(20) = 60\\) to find \\(k\\).", workingLatex: "40 = 80\\,e^{-20k} \\;\\Rightarrow\\; e^{-20k} = \\displaystyle\\frac{1}{2} \\;\\Rightarrow\\; k = \\displaystyle\\frac{\\ln 2}{20}", explanation: "After \\(20\\) minutes the gap has halved — a half-life of \\(20\\) min for the gap." }, { stepNumber: 5, description: "Set \\(T = 30\\) and solve for \\(t\\).", workingLatex: "10 = 80\\,e^{-kt} \\;\\Rightarrow\\; e^{-kt} = \\displaystyle\\frac{1}{8} \\;\\Rightarrow\\; kt = \\ln 8 = 3\\ln 2", explanation: "Gap reduced by a factor of \\(8\\), i.e. three half-lives." }, { stepNumber: 6, description: "Solve.", workingLatex: "t = \\displaystyle\\frac{3\\ln 2}{k} = \\displaystyle\\frac{3\\ln 2}{(\\ln 2)/20} = 3\\cdot 20 = 60 \\text{ min}", explanation: "The half-life of the gap is \\(20\\) min, so three half-lives is \\(60\\) min." }, { stepNumber: 7, description: "Verify.", workingLatex: "T(60) = 20 + 80\\,e^{-60(\\ln 2)/20} = 20 + 80\\,e^{-3\\ln 2} = 20 + 80\\cdot\\displaystyle\\frac{1}{8} = 30 \\;\\checkmark", explanation: "Confirms the time to cool to \\(30\\) °C is exactly \\(60\\) minutes." } ], finalAnswer: "60 minutes." } },
  { id: "y2in10-066", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 66", difficulty: "Challenge", questionText: "A weight hangs from a spring and bounces; amplitude decays as \\(\\displaystyle\\frac{dA}{dt} = -0.1A\\). If the initial amplitude is 5 cm, find it after 20 seconds.", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Interpret the model.", workingLatex: "\\displaystyle\\frac{dA}{dt} = -0.1\\,A", explanation: "The envelope of a damped oscillation: amplitude decays exponentially at \\(0.1\\) per second. The actual displacement oscillates inside this envelope but we only care about the envelope here." }, { stepNumber: 2, description: "Identify the DE type and solve.", workingLatex: "A(t) = A_{0}\\,e^{-0.1 t}", explanation: "Exponential-decay template; separable, with integrating step \\(\\displaystyle\\int dA/A = \\displaystyle\\int -0.1\\,dt\\)." }, { stepNumber: 3, description: "Apply IC \\(A(0) = 5\\) cm.", workingLatex: "A(t) = 5\\,e^{-0.1 t}", explanation: "Plug in the initial amplitude." }, { stepNumber: 4, description: "Evaluate at \\(t = 20\\).", workingLatex: "A(20) = 5\\,e^{-0.1\\cdot 20} = 5\\,e^{-2}", explanation: "The exponent reduces to \\(-2\\)." }, { stepNumber: 5, description: "Numerical value.", workingLatex: "A(20) \\approx 5 \\cdot 0.1353 \\approx 0.677 \\text{ cm}", explanation: "Using \\(e^{-2} \\approx 0.1353\\). The amplitude has shrunk to about \\(\\displaystyle\\frac{1}{7}\\) of its starting value." }, { stepNumber: 6, description: "Sanity check via half-life.", workingLatex: "T_{1/2} = \\displaystyle\\frac{\\ln 2}{0.1} \\approx 6.93 \\text{ s};\\;\\; 20/6.93 \\approx 2.89 \\text{ half-lives}", explanation: "About \\((1/2)^{2.89} \\approx 0.135\\) of the initial \\(5\\) cm — matching the value found." } ], finalAnswer: "\\(\\approx 0.677\\) cm." } },
  { id: "y2in10-067", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 67", difficulty: "Challenge", questionText: "In a logistic model with carrying capacity \\(M = 1000\\), when \\(P = 500\\) growth rate is 50/time. Find the parameter \\(k\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify the model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = k\\,P\\,(M - P),\\;\\; M = 1000", explanation: "Standard logistic DE with carrying capacity \\(M = 1000\\). The product \\(P(M - P)\\) drives growth that is fastest at \\(P = M/2\\) and zero at \\(P = 0, M\\)." }, { stepNumber: 2, description: "Substitute the given data point.", workingLatex: "\\displaystyle\\frac{dP}{dt}\\bigg|_{P=500} = k\\cdot 500\\cdot (1000 - 500) = k\\cdot 500\\cdot 500 = 50", explanation: "At \\(P = 500\\) the growth rate is \\(50\\); plug \\(P\\) and \\(dP/dt\\) into the logistic DE." }, { stepNumber: 3, description: "Solve for \\(k\\).", workingLatex: "k\\cdot 250000 = 50 \\;\\Rightarrow\\; k = \\displaystyle\\frac{50}{250000} = 2\\times 10^{-4}", explanation: "Divide through. The parameter has units of (population\\(^{-1}\\) time\\(^{-1}\\))." }, { stepNumber: 4, description: "Reinterpret using the alternative form.", workingLatex: "\\displaystyle\\frac{dP}{dt} = r P\\!\\left(1 - \\displaystyle\\frac{P}{M}\\right),\\;\\; r = kM", explanation: "Many texts use intrinsic growth rate \\(r = kM\\). Here \\(r = 2\\times 10^{-4}\\cdot 1000 = 0.2\\) per unit time — the per-capita growth rate when \\(P \\ll M\\)." }, { stepNumber: 5, description: "Sanity-check the maximum growth rate.", workingLatex: "\\left.\\displaystyle\\frac{dP}{dt}\\right|_{\\max} = \\displaystyle\\frac{rM}{4} = \\displaystyle\\frac{0.2\\cdot 1000}{4} = 50", explanation: "The logistic peak rate is at \\(P = M/2 = 500\\) — exactly where the given data lies, so \\(50\\) is the model's maximum rate." }, { stepNumber: 6, description: "Verify by substituting \\(k\\) back.", workingLatex: "k\\cdot 500\\cdot 500 = (2\\times 10^{-4})(250000) = 50 \\;\\checkmark", explanation: "Recovers the given rate, confirming the value of \\(k\\)." }, { stepNumber: 7, description: "State the answer.", workingLatex: "k = 2\\times 10^{-4}", explanation: "Equivalently \\(r = kM = 0.2\\) per unit time." } ], finalAnswer: "\\(k = 2 \\times 10^{-4}\\)." } },
  { id: "y2in10-068", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 68", difficulty: "Challenge", questionText: "Describe the long-term behaviour of solutions of \\(\\displaystyle\\frac{dy}{dt} = y - y^2\\) for \\(y > 0\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["modelling", "logistic"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise the model.", workingLatex: "\\displaystyle\\frac{dy}{dt} = y - y^{2} = y(1 - y)", explanation: "Logistic DE with intrinsic growth rate \\(1\\) and carrying capacity \\(1\\). Factoring exposes the steady states directly." }, { stepNumber: 2, description: "Find the steady states.", workingLatex: "y(1 - y) = 0 \\;\\Rightarrow\\; y = 0 \\text{ or } y = 1", explanation: "Set the right-hand side to zero. These are the only equilibrium points." }, { stepNumber: 3, description: "Determine stability by sign analysis.", workingLatex: "\\begin{cases} 0 < y < 1: & y(1-y) > 0 \\Rightarrow y' > 0,\\;\\; y \\text{ increases towards } 1 \\\\ y > 1: & y(1-y) < 0 \\Rightarrow y' < 0,\\;\\; y \\text{ decreases towards } 1 \\end{cases}", explanation: "Trajectory flow on either side of \\(y = 1\\) points towards \\(1\\), so \\(y = 1\\) is asymptotically stable. Trajectory flow at \\(y = 0\\) (a sliver above) points away from \\(0\\), so \\(0\\) is unstable." }, { stepNumber: 4, description: "Linear stability check (optional).", workingLatex: "f(y) = y - y^{2},\\;\\; f'(y) = 1 - 2y;\\;\\; f'(0) = 1 > 0,\\;\\; f'(1) = -1 < 0", explanation: "The sign of \\(f'\\) at each equilibrium confirms the stability conclusions: positive at \\(0\\) (unstable), negative at \\(1\\) (stable)." }, { stepNumber: 5, description: "Conclude.", workingLatex: "y(0) > 0 \\;\\Rightarrow\\; y(t) \\to 1 \\text{ as } t \\to \\infty", explanation: "Any positive initial condition leads to \\(y \\to 1\\); the model is the canonical example of bounded growth approaching carrying capacity." }, { stepNumber: 6, description: "Verify by an explicit solution.", workingLatex: "y(t) = \\displaystyle\\frac{1}{1 + Ce^{-t}};\\;\\; \\lim_{t\\to\\infty} y(t) = \\displaystyle\\frac{1}{1 + 0} = 1 \\;\\checkmark", explanation: "The standard logistic solution confirms the long-term limit \\(y \\to 1\\) for every positive starting value." } ], finalAnswer: "Solutions tend to \\(y = 1\\) for \\(y(0) > 0\\)." } },
  { id: "y2in10-069", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 69", difficulty: "Standard", questionText: "Using \\(V(t) = V_{\\max}\\left(1 - e^{-kt}\\right)\\), find the time for \\(V = V_{\\max}/2\\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["modelling"], workedSolution: { steps: [ { stepNumber: 1, description: "Set the target.", workingLatex: "V_{\\max}\\!\\left(1 - e^{-kt}\\right) = \\displaystyle\\frac{V_{\\max}}{2}", explanation: "Substitute \\(V = V_{\\max}/2\\) into the saturation model." }, { stepNumber: 2, description: "Cancel \\(V_{\\max}\\) and rearrange.", workingLatex: "1 - e^{-kt} = \\displaystyle\\frac{1}{2} \\;\\Rightarrow\\; e^{-kt} = \\displaystyle\\frac{1}{2}", explanation: "Divide both sides by \\(V_{\\max}\\) (non-zero), then move the exponential across." }, { stepNumber: 3, description: "Take logs.", workingLatex: "-kt = \\ln\\!\\left(\\displaystyle\\frac{1}{2}\\right) = -\\ln 2", explanation: "\\(\\ln(1/2) = -\\ln 2\\), so the minus signs cancel." }, { stepNumber: 4, description: "Solve for \\(t\\).", workingLatex: "t = \\displaystyle\\frac{\\ln 2}{k}", explanation: "Divide by \\(k\\). This is the half-saturation time — the analogue of a half-life, but with the upper plateau \\(V_{\\max}\\) playing the role of the ceiling." }, { stepNumber: 5, description: "Verify.", workingLatex: "V\\!\\left(\\displaystyle\\frac{\\ln 2}{k}\\right) = V_{\\max}\\!\\left(1 - e^{-\\ln 2}\\right) = V_{\\max}\\!\\left(1 - \\displaystyle\\frac{1}{2}\\right) = \\displaystyle\\frac{V_{\\max}}{2} \\;\\checkmark", explanation: "Substituting back recovers half of \\(V_{\\max}\\)." }, { stepNumber: 6, description: "Interpret.", workingLatex: "t_{1/2} = \\displaystyle\\frac{\\ln 2}{k}", explanation: "Same functional form as the radioactive half-life — controlled by the time constant \\(1/k\\)." } ], finalAnswer: "\\(t = \\displaystyle\\frac{\\ln 2}{k}\\)." } },
  { id: "y2in10-070", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 70", difficulty: "Foundation", questionText: "Explain the difference between exponential and logistic population models and when each is appropriate.", marks: 3, examStyle: false, yearCreated: 2026, tags: ["concept"], workedSolution: { steps: [ { stepNumber: 1, description: "State the exponential model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = kP \\;\\Rightarrow\\; P(t) = P_{0}\\,e^{kt}", explanation: "Per-capita growth rate \\(k\\) is constant: every individual contributes the same amount per unit time, regardless of how large the population is. Solutions grow (or decay) without bound." }, { stepNumber: 2, description: "State the logistic model.", workingLatex: "\\displaystyle\\frac{dP}{dt} = kP(M - P) \\;\\Rightarrow\\; P(t) \\to M", explanation: "Per-capita growth rate \\(k(M - P)\\) decreases as \\(P\\) rises towards the carrying capacity \\(M\\). Solutions saturate at \\(M\\)." }, { stepNumber: 3, description: "Compare behaviour for small \\(P\\).", workingLatex: "P \\ll M \\;\\Rightarrow\\; kP(M - P) \\approx kMP", explanation: "When the population is far below capacity, the logistic equation is approximately exponential — the two models agree initially." }, { stepNumber: 4, description: "Compare behaviour for large \\(P\\).", workingLatex: "P \\to M \\;\\Rightarrow\\; \\displaystyle\\frac{dP}{dt} \\to 0", explanation: "Logistic growth flattens off near the carrying capacity; exponential growth keeps accelerating without limit." }, { stepNumber: 5, description: "Appropriateness.", workingLatex: "\\text{Exponential: short-term, unconstrained resources. Logistic: long-term, bounded environment.}", explanation: "Use exponential when resources are essentially unlimited (e.g. early-stage epidemic spread, bacteria in fresh medium, compound interest). Use logistic when there is a clear environmental ceiling — finite food, space, or substrate." }, { stepNumber: 6, description: "Summary.", workingLatex: "\\text{Exponential: } P' = kP;\\;\\;\\text{Logistic: } P' = kP(M - P)", explanation: "The defining mathematical distinction is whether the per-capita rate is constant (exponential) or population-dependent and self-limiting (logistic)." } ], finalAnswer: "Exponential: unconstrained growth, \\(\\displaystyle\\frac{dP}{dt} = kP\\); suitable when resources unlimited. Logistic: includes carrying capacity, \\(\\displaystyle\\frac{dP}{dt} = kP(M - P)\\); suitable for bounded environments." } },
  { id: "y2in10-071", topicRef: "y2in10", topicTitle: "Modelling with Differential Equations 71", difficulty: "Challenge", questionText: "A 500-L tank starts with 50 kg of dissolved salt. Water with salt concentration 0.2 kg/L enters at 10 L/min; mixture leaves at 10 L/min. Find \\(S(t)\\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["mixing"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the mixing model.", workingLatex: "\\displaystyle\\frac{dS}{dt} = (\\text{rate in}) - (\\text{rate out})", explanation: "Conservation of salt: rate of change equals salt flowing in minus salt flowing out per unit time. Since inflow and outflow rates are equal, the tank volume stays at \\(500\\) L." }, { stepNumber: 2, description: "Compute rate in.", workingLatex: "\\text{rate in} = 0.2\\text{ kg/L} \\cdot 10\\text{ L/min} = 2\\text{ kg/min}", explanation: "Concentration times volumetric flow gives the mass flow rate of salt entering." }, { stepNumber: 3, description: "Compute rate out.", workingLatex: "\\text{rate out} = \\displaystyle\\frac{S}{500}\\text{ kg/L} \\cdot 10\\text{ L/min} = \\displaystyle\\frac{S}{50}\\text{ kg/min}", explanation: "Assuming instantaneous mixing, the outgoing concentration equals the current tank concentration \\(S/500\\), so the outgoing salt flow rate is \\(S/50\\)." }, { stepNumber: 4, description: "Assemble the DE.", workingLatex: "\\displaystyle\\frac{dS}{dt} = 2 - \\displaystyle\\frac{S}{50}", explanation: "Linear first-order with constant coefficients and constant forcing — classic mixing-problem template." }, { stepNumber: 5, description: "Find the equilibrium and solve.", workingLatex: "S^{*} = 2\\cdot 50 = 100;\\;\\; S = 100 + Be^{-t/50}", explanation: "Steady-state concentration is \\(0.2\\) kg/L throughout — i.e. \\(100\\) kg in \\(500\\) L. General solution is equilibrium plus exponential decay of the deviation." }, { stepNumber: 6, description: "Apply IC \\(S(0) = 50\\).", workingLatex: "50 = 100 + B \\;\\Rightarrow\\; B = -50", explanation: "Substituting \\(t = 0\\) pins the constant. The tank starts below the equilibrium concentration, so \\(B < 0\\)." }, { stepNumber: 7, description: "Write the explicit solution.", workingLatex: "S(t) = 100 - 50\\,e^{-t/50}", explanation: "Salt mass rises monotonically from \\(50\\) kg towards the asymptote \\(100\\) kg with time constant \\(50\\) min." }, { stepNumber: 8, description: "Verify by substituting into the DE.", workingLatex: "\\displaystyle\\frac{dS}{dt} = e^{-t/50};\\;\\; 2 - \\displaystyle\\frac{S}{50} = 2 - 2 + e^{-t/50} = e^{-t/50} \\;\\checkmark", explanation: "Both sides agree, confirming the solution. Long term, the tank's salt content saturates at \\(100\\) kg — corresponding to the inflow concentration of \\(0.2\\) kg/L throughout the \\(500\\) L tank." } ], finalAnswer: "\\(S(t) = 100 - 50e^{-t/50}\\); steady-state 100 kg." } },
];
